const rows:Record<string,Draft>={
  "WEKA Intelligence":["https://www.weka.de/", "WEKA Intelligence verbindet Fachinformationen, Software und Schulungen für betriebliche Sicherheit, Bau, Technik und Verwaltung. Unternehmen nutzen etwa EHS-Management, CE-Dokumentation und Unterweisung; Fachwissen und Workflow-Software sind unterschiedliche Leistungen. Bei der Auswahl zählen Aktualität der Inhalte, Verantwortlichkeiten für rechtliche Freigaben, Nutzerrechte und Integration in bestehende Prozesse. Eine Vorlage ersetzt keine standortbezogene Gefährdungsbeurteilung oder juristische Einzelfallprüfung.", "WEKA Intelligence combines specialist knowledge, software and training for occupational safety, construction, engineering and public administration. Companies use EHS management, CE documentation and instruction, while content and workflow software are distinct services. Selection should cover content currency, legal sign-off responsibilities, user rights and integration into existing processes. A template cannot replace a site-specific risk assessment or individual legal review.", "EHS;CE-Dokumentation;Arbeitsschutz;Fachinformationen;Unterweisung;Bau;Verwaltung", "EHS;CE documentation;Occupational safety;Specialist content;Training;Construction;Public administration", "Arbeitsschutz;EHS;Qualitätsmanagement;Technik;Personal;Verwaltung;Einkauf", "Safety;EHS;Quality management;Engineering;HR;Administration;Procurement"],
  "Hewlett Packard Enterprise":["https://www.hpe.com/", "Hewlett Packard Enterprise liefert Server, Speicher, Netzwerke und hybride Cloud-Angebote für Unternehmen. GreenLake bündelt nutzungsorientierte Infrastrukturleistungen; Aruba Networking adressiert Campus- und Rechenzentrumsnetze. Käufer sollten Workloads, Datenstandorte, Schnittstellen, Betriebspartner und Vertragsgrenzen je Angebot prüfen. Ein Herstellerportfolio ist keine einheitliche Cloud: Hardware, Managed Service und Verbrauchsmodell haben unterschiedliche Zuständigkeiten und Kostenrisiken.", "Hewlett Packard Enterprise supplies servers, storage, networking and hybrid cloud offerings for organisations. GreenLake packages consumption-based infrastructure services; Aruba Networking addresses campus and data-centre networks. Buyers should assess workloads, data locations, interfaces, operating partners and contract boundaries by offer. A vendor portfolio is not one uniform cloud: hardware, managed services and consumption models carry different responsibilities and cost risks.", "Server;Storage;GreenLake;Aruba Networking;Hybrid Cloud;KI-Infrastruktur;Betriebsmodelle", "Servers;Storage;GreenLake;Aruba Networking;Hybrid cloud;AI infrastructure;Operating models", "CIO;Rechenzentrum;Netzwerk;Cloud-Architektur;Finanzen;IT-Betrieb;Einkauf", "CIO;Data centres;Networks;Cloud architecture;Finance;IT operations;Procurement"],
  "Reply":["https://www.reply.com/", "Reply ist ein Verbund spezialisierter Unternehmen für digitale Plattformen, Cloud, Daten, KI und Kundenprozesse. Projekte werden durch passende Teams und Partnertechnologien umgesetzt; ein Referenzprojekt einer Gruppengesellschaft gilt nicht automatisch für jede andere. Auftraggeber sollten fachliche Zuständigkeit, verwendete Plattformen, Übergabe in den Betrieb, Datenrechte und konkrete Vertragspartei klären. Bei komplexen Programmen zählt die Integration der Einzelprojekte mehr als ein breites Schlagwortportfolio.", "Reply is a group of specialist companies working on digital platforms, cloud, data, AI and customer processes. Projects use relevant teams and partner technologies; a reference from one group company does not automatically apply to another. Buyers should clarify delivery responsibility, platforms, transition to operations, data rights and the actual contracting entity. In complex programmes, integration between workstreams matters more than the breadth of the portfolio.", "Cloud;Datenplattformen;KI-Projekte;Systemintegration;Commerce;Customer Experience;Beratung", "Cloud;Data platforms;AI projects;Systems integration;Commerce;Customer experience;Consulting", "CIO;Digitalstrategie;Datenleitung;Marketing;Architektur;Fachbereiche;Einkauf", "CIO;Digital strategy;Data leadership;Marketing;Architecture;Business units;Procurement"],
  "Alteryx":["https://www.alteryx.com/", "Alteryx bietet Werkzeuge zur Aufbereitung, Analyse und Automatisierung von Daten für Fachabteilungen und Analytics-Teams. Workflows verknüpfen Quellen und Berechnungen, bevor Ergebnisse in Berichte oder Entscheidungen eingehen. Käufer sollten Datenzugriffe, Versionierung, Deployment, Governance und Laufzeitkosten anhand realer Abläufe testen. Self-Service bedeutet nicht, dass Datenqualität und fachliche Definitionen ohne Eigentümer auskommen; wiederverwendete Workflows brauchen dokumentierte Kontrollen.", "Alteryx provides tools to prepare, analyse and automate data for business and analytics teams. Workflows combine sources and calculations before outputs feed reports or decisions. Buyers should test data access, versioning, deployment, governance and runtime cost against real processes. Self-service does not remove ownership of data quality and business definitions; reusable workflows need documented controls.", "Datenaufbereitung;Analytics-Automatisierung;Workflows;Self-Service;Governance;Integration;Reporting", "Data preparation;Analytics automation;Workflows;Self-service;Governance;Integration;Reporting", "Data Science;Controlling;Finanzen;IT-Architektur;BI;Compliance;Einkauf", "Data science;Controlling;Finance;IT architecture;BI;Compliance;Procurement"],
  "Controlware":["https://www.controlware.de/", "Controlware integriert und betreibt IT-Infrastruktur für Netzwerke, Informationssicherheit, Rechenzentrum und Cloud. Dazu kommen Beratungs- und Managed Services, deren Leistungsumfang vom Projekt und Vertrag abhängt. Unternehmen sollten Herstellerprodukte und Controlwares eigene Betriebsaufgaben unterscheiden: Eskalation, Monitoring, Patch-Verantwortung und Wiederherstellung müssen konkret vereinbart werden. Für Cyberabwehr sind vorhandene Werkzeuge, Reaktionszeiten und Zuständigkeiten im Incident wichtiger als eine pauschale Sicherheitszusage.", "Controlware integrates and operates IT infrastructure across networking, information security, data centres and cloud. Consulting and managed services vary by project and contract. Organisations should distinguish vendor products from Controlware's operational duties: escalation, monitoring, patch ownership and recovery need explicit agreement. For cyber defence, existing tools, response times and incident responsibilities matter more than a general security claim.", "Netzwerke;Cybersecurity;Cloud;Rechenzentrum;Managed Services;Monitoring;Integration", "Networking;Cybersecurity;Cloud;Data centres;Managed services;Monitoring;Integration", "CIO;CISO;Netzwerkbetrieb;Cloud;Rechenzentrum;Service Management;Einkauf", "CIO;CISO;Network operations;Cloud;Data centres;Service management;Procurement"],
  "Censys":["https://censys.com/", "Censys untersucht öffentlich erreichbare digitale Angriffsflächen und unterstützt Sicherheits-Teams beim Auffinden exponierter Systeme. Die Daten helfen, Assets und Fehlkonfigurationen zu priorisieren; eine gefundene IP-Adresse muss jedoch vor Maßnahmen dem eigenen Bestand zugeordnet werden. Käufer sollten Abdeckung, Scanfrequenz, historische Sicht, API-Anbindung und Alarmqualität testen. Externe Sicht allein zeigt weder interne Schwachstellen vollständig noch die tatsächliche Ausnutzbarkeit eines Befunds.", "Censys maps internet-exposed attack surfaces and helps security teams find exposed systems. Its data can prioritise assets and misconfigurations, but an identified IP address must be attributed to the organisation before action. Buyers should test coverage, scan frequency, historical context, API integration and alert quality. An external view cannot fully reveal internal vulnerabilities or the exploitability of a finding.", "Angriffsflächen;Asset Discovery;Internet-Scanning;Exponierung;API;Schwachstellenpriorisierung;Monitoring", "Attack surface;Asset discovery;Internet scanning;Exposure;API;Vulnerability prioritisation;Monitoring", "CISO;SOC;Threat Intelligence;IT-Betrieb;Cloud Security;Incident Response;Einkauf", "CISO;SOC;Threat intelligence;IT operations;Cloud security;Incident response;Procurement"],
  "Google Cloud":["https://cloud.google.com/products", "Google Cloud stellt Infrastruktur, Datenplattformen, KI-Dienste und Werkzeuge für Anwendungen bereit. BigQuery, Kubernetes und Vertex AI adressieren unterschiedliche Architekturebenen; die passende Kombination hängt von Datenwegen, Fähigkeiten und Betriebsmodell ab. Käufer sollten Regionen, Berechtigungen, Kostenkontrolle, Exit und Sicherheitsverantwortung je Dienst prüfen. Eine KI-Demo ersetzt weder die fachliche Evaluation noch die Kontrolle von Trainings- und Kundendaten.", "Google Cloud provides infrastructure, data platforms, AI services and application tooling. BigQuery, Kubernetes and Vertex AI address distinct architectural layers; their combination depends on data flows, team skills and operating model. Buyers should evaluate regions, permissions, cost controls, exit options and security responsibilities per service. An AI demo cannot replace business evaluation or governance of training and customer data.", "Compute;BigQuery;Kubernetes;Vertex AI;Cloud-Sicherheit;Datenplattform;Migration", "Compute;BigQuery;Kubernetes;Vertex AI;Cloud security;Data platform;Migration", "CIO;Cloud-Architektur;Data Engineering;KI-Teams;CISO;FinOps;Einkauf", "CIO;Cloud architecture;Data engineering;AI teams;CISO;FinOps;Procurement"],
  "Randstad Deutschland":["https://www.randstad.de/unternehmen/", "Randstad Deutschland bietet Personaldienstleistungen für Unternehmen, darunter Zeitarbeit, Personalvermittlung und weitere Recruiting-Angebote. Welche Leistung verfügbar ist, hängt von Qualifikation, Region und konkretem Vertragsmodell ab. Auftraggeber sollten Besetzungsdauer, Einsatzbedingungen, Qualifikationsprüfung, Betreuung und Datenschutz klären. Arbeitsmarktstudien liefern Kontext, aber keine Zusage für die Verfügbarkeit gesuchter Fachkräfte am eigenen Standort.", "Randstad Deutschland provides staffing services for employers, including temporary staffing, permanent placement and other recruitment offerings. Availability varies by skill, region and contract model. Buyers should agree on time to fill, assignment conditions, qualification checks, support and data privacy. Labour market studies give context but do not promise the availability of specific skills at a given location.", "Zeitarbeit;Personalvermittlung;Recruiting;Fachkräfte;Arbeitgeberberatung;Onboarding;Arbeitsmarkt", "Temporary staffing;Permanent placement;Recruitment;Specialists;Employer advice;Onboarding;Labour market", "HR;Talent Acquisition;Standortleitung;Produktion;Recht;Personalplanung;Einkauf", "HR;Talent acquisition;Site management;Production;Legal;Workforce planning;Procurement"],
  "Tenable":["https://www.tenable.com/products", "Tenable bietet Plattformen zur Bewertung von Cyberrisiken in IT, Cloud und operativer Technologie. Erfasste Schwachstellen und Exponierungen müssen auf geschäftskritische Assets, Eigentümer und realistische Abhilfemaßnahmen bezogen werden. Käufer sollten Sensorabdeckung, Authentifizierung, Priorisierung, Ticketintegration und Reporting prüfen. Ein Risikoscore allein beseitigt keine Schwachstelle; Betriebsteams brauchen abgestimmte Wartungsfenster und überprüfbare Ausnahmen.", "Tenable offers platforms to assess cyber risk across IT, cloud and operational technology. Vulnerabilities and exposures need mapping to critical assets, owners and feasible remediation. Buyers should examine sensor coverage, authentication, prioritisation, ticket integration and reporting. A risk score does not remove a vulnerability; operations teams need agreed maintenance windows and auditable exceptions.", "Vulnerability Management;Exposure Management;Cloud Security;OT-Sicherheit;Asset Discovery;Priorisierung;Reporting", "Vulnerability management;Exposure management;Cloud security;OT security;Asset discovery;Prioritisation;Reporting", "CISO;SOC;IT-Betrieb;OT-Betrieb;Cloud Security;Risikomanagement;Einkauf", "CISO;SOC;IT operations;OT operations;Cloud security;Risk management;Procurement"],
  "SAP Concur":["https://www.concur.de/", "SAP Concur bietet Cloud-Anwendungen für Geschäftsreisen, Spesen und Rechnungsprozesse. Richtlinien, Genehmigungen und Belege müssen mit ERP, Zahlungswegen und lokaler Steuerpraxis zusammenpassen. Käufer sollten Länderabdeckung, Mobilnutzung, Integrationen, Freigaberollen und Abrechnung je Modul prüfen. Automatische Belegerfassung kann manuelle Kontrolle verringern, ersetzt aber weder die steuerliche Prüfung noch die klare Verantwortung für Ausnahmen.", "SAP Concur offers cloud applications for business travel, expenses and invoice processes. Policies, approvals and receipts must fit ERP, payments and local tax practices. Buyers should assess country coverage, mobile use, integrations, approval roles and billing by module. Automatic receipt capture can reduce manual work but cannot replace tax review or clear responsibility for exceptions.", "Reisemanagement;Spesen;Eingangsrechnungen;Genehmigungen;ERP-Integration;Belege;Compliance", "Travel management;Expenses;Supplier invoices;Approvals;ERP integration;Receipts;Compliance", "Finanzen;Travel Management;HR;ERP;Compliance;IT;Einkauf", "Finance;Travel management;HR;ERP;Compliance;IT;Procurement"],
  "Splunk Services Germany":["https://www.splunk.com/", "Splunk verarbeitet Maschinen- und Ereignisdaten für Observability und Sicherheitsanalysen. Die deutsche Serviceeinheit im Katalog verweist auf das Splunk-Portfolio; Vertrags- und Supportzuständigkeiten sind gesondert festzustellen. Käufer sollten Datenquellen, Aufbewahrung, Suchperformance, Lizenzmetrik und Eskalation bei Alarmen testen. Dashboards liefern Sichtbarkeit, aber ohne Datenqualität und feste Incident-Prozesse keine belastbare Reaktion.", "Splunk processes machine and event data for observability and security analytics. The German service entity in the catalogue points to the Splunk portfolio; contract and support responsibility needs separate confirmation. Buyers should test data sources, retention, search performance, licensing metrics and alert escalation. Dashboards provide visibility, but without data quality and defined incident processes they cannot ensure effective response.", "Log-Analyse;Observability;SIEM;Datenaufnahme;Alerts;Dashboards;Incident Response", "Log analytics;Observability;SIEM;Data ingestion;Alerts;Dashboards;Incident response", "SOC;SRE;IT-Betrieb;CISO;Plattformteams;Datenarchitektur;Einkauf", "SOC;SRE;IT operations;CISO;Platform teams;Data architecture;Procurement"],
  "Plaid":["https://plaid.com/products/", "Plaid bietet Schnittstellen für Finanzanwendungen, etwa zur Verbindung von Konten und zur Nutzung autorisierter Finanzdaten. Welche Daten und Zahlungsfunktionen nutzbar sind, hängt von Markt, Bank und Einwilligung ab. Käufer sollten API-Abdeckung, Ausfälle, Datenminimierung, Einwilligungsabläufe und vertragliche Verantwortlichkeiten prüfen. Ein erfolgreicher Kontozugriff belegt weder Bonität noch die Eignung für jede regulatorische Anwendung.", "Plaid provides interfaces for financial applications to connect accounts and use authorised financial data. Available data and payment functions depend on market, institution and consent. Buyers should assess API coverage, outages, data minimisation, consent flows and contractual responsibilities. A successful account connection does not establish creditworthiness or suitability for every regulated use case.", "Kontoverbindung;Finanz-APIs;Identität;Zahlungsdaten;Einwilligung;Integration;Datenzugang", "Account connections;Financial APIs;Identity;Payment data;Consent;Integration;Data access", "Fintech;Produktmanagement;Banking;Compliance;Datenschutz;Entwicklung;Einkauf", "Fintech;Product management;Banking;Compliance;Privacy;Engineering;Procurement"],
  "Akeneo":["https://www.akeneo.com/", "Akeneo entwickelt Product Information Management für Hersteller und Händler. Die Plattform unterstützt die Pflege von Produktdaten und ihre Ausgabe in unterschiedliche Vertriebs- und Kommunikationskanäle. Käufer sollten Datenmodell, Varianten, Übersetzung, Medienanbindung und Integration in ERP und Shops anhand echter Sortimente prüfen. Höhere Datenqualität entsteht durch klare Eigentümer und Freigaben; Software allein korrigiert unvollständige Produktdaten nicht.", "Akeneo develops product information management for manufacturers and retailers. Its platform supports maintaining product data and distributing it to sales and communication channels. Buyers should test the data model, variants, translation, media links and ERP and shop integrations against real assortments. Better data quality requires clear ownership and approvals; software alone cannot correct incomplete product records.", "PIM;Produktdaten;Varianten;Omnichannel;Übersetzung;ERP-Integration;Datenqualität", "PIM;Product data;Variants;Omnichannel;Translation;ERP integration;Data quality", "E-Commerce;Produktmanagement;Marketing;Datenmanagement;IT;Vertrieb;Einkauf", "E-commerce;Product management;Marketing;Data management;IT;Sales;Procurement"],
  "Samsara":["https://www.samsara.com/", "Samsara verbindet Telematik, Kameras und Betriebsdaten für Fahrzeugflotten und andere physische Abläufe. Anwendungen reichen von Flottentransparenz bis zu Sicherheit und Wartung; der Nutzen hängt von Fahrzeugbestand und Einführung im Betrieb ab. Käufer sollten Hardware, Konnektivität, Fahrerrechte, Datenschutz, Integration und Auswertung konkreter Ereignisse prüfen. Ein Fahrerscore braucht nachvollziehbare Regeln und angemessene Beteiligung der Beschäftigten.", "Samsara combines telematics, cameras and operational data for fleets and other physical operations. Use cases range from fleet visibility to safety and maintenance; value depends on the fleet and operational rollout. Buyers should evaluate hardware, connectivity, driver rights, privacy, integration and analysis of actual events. Driver scores need transparent rules and appropriate employee involvement.", "Flottentelematik;Fahrzeugkameras;Wartung;Sicherheit;IoT;Routen;Betriebsdaten", "Fleet telematics;Vehicle cameras;Maintenance;Safety;IoT;Routing;Operational data", "Flottenleitung;Logistik;Arbeitsschutz;IT;Datenschutz;Betriebsrat;Einkauf", "Fleet management;Logistics;Safety;IT;Privacy;Works council;Procurement"],
  "Siemens":["https://www.siemens.com/en-us/company/about/businesses/digital-industries/", "Siemens deckt Automatisierung, industrielle Software und Infrastruktur in zahlreichen Geschäftsfeldern ab. Im SmartTech-Katalog betreffen viele Inhalte Engineering, Digital Twin, Fertigung und Produktlebenszyklus; diese bilden nur einen Ausschnitt. Käufer sollten Hardware- und Softwarezuständigkeiten, Datenmodelle, Schnittstellen, Lizenzierung und den Betrieb über Werksgrenzen prüfen. Aussagen einer Siemens-Sparte lassen sich nicht ohne Weiteres auf alle Konzernangebote übertragen.", "Siemens spans automation, industrial software and infrastructure across many businesses. In the SmartTech catalogue, much content concerns engineering, digital twins, manufacturing and product lifecycle, which represent only a subset. Buyers should assess hardware and software responsibilities, data models, interfaces, licensing and operation across plants. Claims from one Siemens division should not automatically be applied across the whole group.", "Industrieautomation;Engineering;Digital Twin;PLM;Fertigung;Industrial IoT;Integration", "Industrial automation;Engineering;Digital twin;PLM;Manufacturing;Industrial IoT;Integration", "Produktion;Engineering;OT;IT-Architektur;PLM;Werksleitung;Einkauf", "Production;Engineering;OT;IT architecture;PLM;Plant management;Procurement"],
  "Aagon":["https://www.aagon.com/", "Aagon entwickelt Software für Unified Endpoint Management und IT-Automatisierung. Unternehmen verwalten damit Clients, Softwareverteilung, Inventarisierung und Sicherheitsaufgaben in heterogenen Umgebungen. Käufer sollten Betriebssysteme, Agenten, Paketierung, Rechte, Netzwerkstandorte und Upgradepfad praktisch testen. Die Konsolidierung von Werkzeugen verspricht geringere Komplexität, benötigt aber einen Plan für Datenmigration und den Weiterbetrieb vorhandener Prozesse.", "Aagon develops unified endpoint management and IT automation software. Organisations use it for client administration, software distribution, inventory and security tasks across mixed environments. Buyers should test operating systems, agents, packaging, permissions, network sites and upgrade paths in practice. Tool consolidation may reduce complexity, but requires a plan for data migration and continued operation of existing processes.", "Endpoint Management;Softwareverteilung;Inventar;Patch Management;Automatisierung;Client-Sicherheit;Reporting", "Endpoint management;Software deployment;Inventory;Patch management;Automation;Client security;Reporting", "IT-Betrieb;Client Management;CISO;Service Desk;Architektur;Compliance;Einkauf", "IT operations;Client management;CISO;Service desk;Architecture;Compliance;Procurement"],
  "Alvarez & Marsal":["https://www.alvarezandmarsal.com/", "Alvarez & Marsal berät Unternehmen bei Transformation, Restrukturierung und operativen Finanzthemen. Leistungsumfang und Team hängen vom Mandat ab; im Katalog beobachtete Marktkommentare sind keine Prüfung individueller Projekte. Auftraggeber sollten Erfahrung im relevanten Sektor, Interessenkonflikte, Messgrößen und Verantwortlichkeiten für die Umsetzung klären. Beratungsempfehlungen benötigen Zugriff auf belastbare Unternehmensdaten und eine Entscheidung durch die zuständigen Organe.", "Alvarez & Marsal advises organisations on transformation, restructuring and operational finance. Scope and teams depend on the engagement; market commentary observed in the catalogue is not a review of individual projects. Buyers should clarify relevant sector experience, conflicts of interest, measures of success and delivery responsibility. Advisory recommendations require reliable company data and decisions by the responsible governing bodies.", "Restrukturierung;Transformation;Performance;Transaktionen;Finanzberatung;Operations;Governance", "Restructuring;Transformation;Performance;Transactions;Financial advisory;Operations;Governance", "Geschäftsführung;CFO;Strategie;Operations;Investoren;Recht;Einkauf", "Executive management;CFO;Strategy;Operations;Investors;Legal;Procurement"],
  "Fortinet":["https://www.fortinet.com/products", "Fortinet bietet Produkte für Netzwerksicherheit, Secure Networking und Security Operations. Firewalls, SASE und weitere Bausteine müssen zur vorhandenen Netzarchitektur und zu Identitätsprozessen passen. Käufer sollten Durchsatz unter aktivierten Schutzfunktionen, Verwaltung, Lizenzen, Protokollierung und Ausfallszenarien testen. Ein Herstellerprodukt allein schafft keine vollständige Abwehr; Regeln, Überwachung und Reaktion müssen im Betrieb gepflegt werden.", "Fortinet provides products for network security, secure networking and security operations. Firewalls, SASE and related components must match the existing network architecture and identity processes. Buyers should test throughput with protection enabled, management, licensing, logging and failure scenarios. A vendor product alone cannot provide complete defence; policies, monitoring and incident response need ongoing operations.", "Firewalls;SASE;SD-WAN;Netzwerksecurity;Security Operations;Zero Trust;Monitoring", "Firewalls;SASE;SD-WAN;Network security;Security operations;Zero Trust;Monitoring", "CISO;Netzwerkleitung;SOC;Cloud Security;IT-Betrieb;Architektur;Einkauf", "CISO;Network leadership;SOC;Cloud security;IT operations;Architecture;Procurement"],
  "AGRAVIS Raiffeisen":["https://www.agravis.de/en/the-company/about-us/brands", "AGRAVIS Raiffeisen verbindet Agrarhandel mit Dienstleistungen für Landwirtschaft und ländliche Räume. Betriebsmittel, Technik, Energie und Vermarktung betreffen unterschiedliche Märkte und Vertragsformen. Geschäftskunden sollten regionale Verfügbarkeit, Lieferkette, Beratung, Wartung und Preisrisiken je Produkt prüfen. Eine Unternehmensmeldung über Ausbildung oder Nachhaltigkeit ist keine Aussage über die Leistung eines konkreten Maschinen- oder Liefervertrags.", "AGRAVIS Raiffeisen combines agricultural trade with services for farms and rural businesses. Inputs, equipment, energy and marketing involve different markets and contracts. Business customers should assess regional availability, supply chains, advice, maintenance and price risks by product. A company announcement about training or sustainability does not establish performance under an individual equipment or supply agreement.", "Agrarhandel;Betriebsmittel;Landtechnik;Energie;Futtermittel;Pflanzenbau;Vermarktung", "Agricultural trade;Farm inputs;Agricultural machinery;Energy;Feed;Crop production;Marketing", "Landwirtschaft;Einkauf;Betriebsleitung;Technik;Logistik;Finanzen;Nachhaltigkeit", "Farming;Procurement;Operations;Engineering;Logistics;Finance;Sustainability"],
  "Ivalua":["https://www.ivalua.com/", "Ivalua bietet eine Plattform für Einkauf und Lieferantenmanagement. Sourcing, Vertragsverwaltung und Procure-to-Pay greifen ineinander, müssen aber an ERP, Stammdaten und interne Freigaben angepasst werden. Käufer sollten Lieferantenanlage, Rechte, Kataloge, Datenexport und Ausnahmen anhand realer Beschaffungsfälle prüfen. KI-Funktionen sollten nachvollziehbare Ergebnisse liefern; die Verantwortung für Vergabeentscheidungen bleibt bei den zuständigen Menschen.", "Ivalua provides a procurement and supplier management platform. Sourcing, contract management and procure-to-pay connect but need alignment with ERP, master data and internal approvals. Buyers should test supplier onboarding, permissions, catalogues, data export and exceptions using real purchasing cases. AI functions should provide traceable outputs; responsibility for award decisions remains with the people authorised to make them.", "Sourcing;Lieferantenmanagement;Procure-to-Pay;Verträge;Kataloge;Analytics;Integration", "Sourcing;Supplier management;Procure-to-pay;Contracts;Catalogues;Analytics;Integration", "Einkauf;Finanzen;Lieferantenmanagement;IT;Compliance;Fachbereiche;Recht", "Procurement;Finance;Supplier management;IT;Compliance;Business units;Legal"],
  "Paessler":["https://www.paessler.com/prtg", "Paessler entwickelt PRTG für die Überwachung von Netzwerken, Servern und IT-Diensten. Sensoren liefern Messwerte und Alarme, deren Nutzen von richtiger Schwelle, Geräteabdeckung und Eskalation abhängt. Käufer sollten Sensorbedarf, Rechte, verteilte Standorte, Schnittstellen und den Betrieb der Monitoring-Plattform testen. Ein grünes Dashboard ersetzt keine End-to-End-Prüfung geschäftskritischer Anwendungen und keine dokumentierte Störungsreaktion.", "Paessler develops PRTG to monitor networks, servers and IT services. Sensors produce measurements and alerts whose value depends on thresholds, device coverage and escalation. Buyers should test sensor needs, permissions, distributed sites, interfaces and operation of the monitoring platform. A green dashboard cannot replace end-to-end checks of critical business applications or a documented incident response.", "PRTG;Netzwerkmonitoring;Sensoren;Serverüberwachung;Alarme;Dashboards;IT-Betrieb", "PRTG;Network monitoring;Sensors;Server monitoring;Alerts;Dashboards;IT operations", "Netzwerkbetrieb;IT-Leitung;Service Desk;Rechenzentrum;SRE;Sicherheit;Einkauf", "Network operations;IT leadership;Service desk;Data centres;SRE;Security;Procurement"],
  "Hyland":["https://www.hyland.com/en/solutions/products", "Hyland bietet Content- und Prozessplattformen für die Verwaltung geschäftlicher Informationen. Dokumentenmanagement, Erfassung und Workflows können Fachprozesse verbinden, benötigen jedoch passende Metadaten und klare Aufbewahrungsregeln. Käufer sollten Migration, Berechtigungen, Integrationen, Suchqualität und den konkreten Betriebsumfang vergleichen. KI-Funktionen für Dokumente sollten mit repräsentativen Originaldaten getestet werden, insbesondere bei vertraulichen und regulierten Inhalten.", "Hyland provides content and process platforms to manage business information. Document management, capture and workflows can connect specialist processes but need suitable metadata and retention rules. Buyers should compare migration, permissions, integration, search quality and operating scope. AI document features should be tested with representative source material, especially for confidential and regulated content.", "Content Management;Dokumentenerfassung;Workflows;Archivierung;Suche;Integration;KI-Dokumente", "Content management;Document capture;Workflows;Archiving;Search;Integration;AI documents", "Informationsmanagement;IT;Compliance;Recht;Fachabteilungen;Archiv;Einkauf", "Information management;IT;Compliance;Legal;Business units;Records;Procurement"],
  "SEPPmail Deutschland":["https://www.seppmail.com/de/", "SEPPmail bietet Lösungen für sichere E-Mail-Kommunikation, Verschlüsselung und digitale Signaturen. In Unternehmen muss die Lösung mit Mailplattform, Zertifikatsprozessen und Kommunikationspartnern zusammenarbeiten. Käufer sollten Schlüsselverwaltung, Zustellbarkeit, Bedienbarkeit, Archivierung und Notfallprozesse testen. Eine verschlüsselte Übertragung schützt Inhalte auf dem Übertragungsweg, ersetzt aber keine Kontrolle falscher Empfänger oder kompromittierter Postfächer.", "SEPPmail offers secure email communication, encryption and digital signatures. In organisations, the solution must work with the mail platform, certificate processes and communication partners. Buyers should test key management, deliverability, usability, archiving and emergency procedures. Encryption in transit protects message contents on the delivery path but cannot prevent misaddressed emails or compromised mailboxes.", "E-Mail-Verschlüsselung;Signaturen;Zertifikate;Gateway;Mail-Integration;Datenschutz;Archivierung", "Email encryption;Signatures;Certificates;Gateway;Mail integration;Privacy;Archiving", "CISO;Mail-Administration;Compliance;Datenschutz;Recht;IT-Betrieb;Einkauf", "CISO;Mail administration;Compliance;Privacy;Legal;IT operations;Procurement"],
  "Getac Technology":["https://www.getac.com/", "Getac liefert robuste mobile Computer für Außendienst, Industrie und öffentliche Einsatzbereiche. Notebooks und Tablets unterscheiden sich bei Schutzklassen, Funkmodulen, Zubehör und Wartung. Käufer sollten die konkrete Geräteklasse mit Handschuhen, Temperatur, Sturzrisiko, Akkutausch und Softwareeinsatz im Feld testen. Ein Gerätegehäuse allein garantiert keine Konnektivität oder Lebensdauer unter allen Einsatzbedingungen.", "Getac supplies rugged mobile computers for field service, industry and public-sector operations. Laptops and tablets differ in protection ratings, radio modules, accessories and service options. Buyers should test the specific device class with gloves, temperature, drops, battery changes and software use in the field. A rugged enclosure alone does not guarantee connectivity or lifetime under every operating condition.", "Rugged Notebooks;Rugged Tablets;Mobile Computing;Funk;Zubehör;Field Service;Gerätemanagement", "Rugged laptops;Rugged tablets;Mobile computing;Wireless;Accessories;Field service;Device management", "Außendienst;IT;Flottenbetrieb;Industrie;Öffentliche Sicherheit;Service;Einkauf", "Field service;IT;Fleet operations;Industry;Public safety;Support;Procurement"],
  "DENIOS":["https://www.denios.de/", "DENIOS bietet Produkte und Services für Gefahrstofflagerung, Arbeitssicherheit und betrieblichen Umweltschutz. Auffangwannen, Sicherheitsschränke und Lagerlösungen müssen zur Stoffklasse, Menge und räumlichen Situation passen. Käufer sollten Zulassungen, Lüftung, Brandschutz, Wartung und Verantwortung für die Installation prüfen. Ein Produktkatalog ersetzt keine standortbezogene Gefährdungsbeurteilung und keine Prüfung der geltenden Lagervorschriften.", "DENIOS supplies products and services for hazardous-material storage, workplace safety and environmental protection. Spill trays, safety cabinets and storage solutions must fit material classes, volumes and local conditions. Buyers should check approvals, ventilation, fire protection, maintenance and installation responsibility. A product catalogue cannot replace a site-specific risk assessment or review of applicable storage rules.", "Gefahrstofflagerung;Auffangsysteme;Brandschutz;Sicherheitsschränke;Arbeitsschutz;Umwelttechnik;Wartung", "Hazardous storage;Containment;Fire protection;Safety cabinets;Occupational safety;Environmental systems;Maintenance", "EHS;Betriebsleitung;Lager;Facility Management;Brandschutz;Technik;Einkauf", "EHS;Operations;Warehousing;Facilities;Fire safety;Engineering;Procurement"],
  "Druva Europe":["https://www.druva.com/products", "Druva bietet Cloud-basierte Datensicherung und Cyber-Resilienz für Unternehmensdaten. Abgedeckte Workloads und Wiederherstellungswege unterscheiden sich je Produkt und Plattform. Käufer sollten Aufbewahrung, Unveränderbarkeit, Datenregion, Bandbreite und reale Restore-Ziele mit Testdaten prüfen. Ein Backup-Status allein beweist keine wiederherstellbare Anwendung; Abhängigkeiten zwischen Identität, Datenbank und Dienst müssen im Notfallplan stehen.", "Druva provides cloud-based data protection and cyber resilience for enterprise information. Covered workloads and recovery paths vary by product and platform. Buyers should test retention, immutability, data region, bandwidth and actual restore objectives using representative data. A successful backup status cannot prove an application is recoverable; dependencies between identity, databases and services belong in the recovery plan.", "Backup;Cloud-Datensicherung;Ransomware-Recovery;SaaS-Schutz;Aufbewahrung;Restore;Compliance", "Backup;Cloud data protection;Ransomware recovery;SaaS protection;Retention;Restore;Compliance", "IT-Betrieb;Backup;CISO;Cloud;Datenschutz;Business Continuity;Einkauf", "IT operations;Backup;CISO;Cloud;Privacy;Business continuity;Procurement"],
  "CADFEM Germany":["https://resources.cadfem.net/de/discover-cadfem-generic", "CADFEM unterstützt Unternehmen bei technischer Simulation mit Software, Beratung und Weiterbildung. Anwendungen reichen von mechanischen bis zu multiphysikalischen Modellen; die Eignung hängt von Modellannahmen und verfügbaren Messdaten ab. Käufer sollten Lizenzierung, Rechenleistung, Schulung, Modellvalidierung und Support für ihren Anwendungsfall klären. Simulationsergebnisse sind nur so belastbar wie Materialdaten, Randbedingungen und fachliche Prüfung.", "CADFEM supports engineering simulation through software, consulting and training. Applications range from mechanical to multiphysics models; suitability depends on model assumptions and available measurements. Buyers should assess licensing, compute capacity, training, model validation and support for their use case. Simulation results are only as reliable as material data, boundary conditions and expert review.", "Simulation;CAE;Ansys;Multiphysik;Schulung;Modellvalidierung;Beratung", "Simulation;CAE;Ansys;Multiphysics;Training;Model validation;Consulting", "Engineering;Forschung;Produktion;CAE;IT;Qualität;Einkauf", "Engineering;Research;Production;CAE;IT;Quality;Procurement"],
  "CoreView":["https://www.coreview.com/", "CoreView bietet Verwaltungs- und Sicherheitswerkzeuge für Microsoft-365-Umgebungen. Teams können Berechtigungen, Konfigurationen und wiederkehrende Administrationsschritte über mehrere Tenants beobachten und steuern. Käufer sollten Rollenmodell, Änderungsnachweise, API-Zugriff, Automatisierungen und Wiederherstellungsmöglichkeiten prüfen. Eine zentrale Oberfläche hebt Microsofts und des Kunden jeweilige Verantwortung für Identität, Daten und Sicherheitskonfiguration nicht auf.", "CoreView offers administration and security tooling for Microsoft 365 estates. Teams can monitor and manage permissions, configurations and recurring administrative tasks across tenants. Buyers should test role models, change evidence, API access, automation and recovery options. A central interface does not remove Microsoft's or the customer's respective responsibilities for identity, data and security configuration.", "Microsoft 365;Tenant-Management;Berechtigungen;Automatisierung;Konfiguration;Audit;Governance", "Microsoft 365;Tenant management;Permissions;Automation;Configuration;Audit;Governance", "M365-Administration;CISO;IT-Betrieb;Compliance;Datenschutz;Service Desk;Einkauf", "M365 administration;CISO;IT operations;Compliance;Privacy;Service desk;Procurement"],
  "Extreme Networks":["https://www.extremenetworks.com/", "Extreme Networks liefert Netzwerktechnik und Management für Unternehmensstandorte und Rechenzentren. Switching, WLAN und Cloud-Management sind unterschiedliche Bausteine, die zu bestehenden Geräten und Betriebsprozessen passen müssen. Käufer sollten Roaming, Kapazität, Redundanz, Policies, Lizenzierung und Support vor Ort testen. Cloud-gesteuertes Netzwerkmanagement benötigt zudem Regeln für Administrationszugriff, Ausfall und Datenstandort.", "Extreme Networks supplies networking and management for enterprise sites and data centres. Switching, wireless and cloud management are distinct components that need to fit existing devices and operations. Buyers should test roaming, capacity, redundancy, policies, licensing and local support. Cloud-managed networking also needs rules for administrative access, outages and data location.", "Switching;WLAN;Netzwerkmanagement;Cloud-Management;Fabric;Campusnetze;Redundanz", "Switching;Wireless;Network management;Cloud management;Fabric;Campus networks;Redundancy", "Netzwerkbetrieb;CIO;Campus-IT;Rechenzentrum;CISO;Architektur;Einkauf", "Network operations;CIO;Campus IT;Data centres;CISO;Architecture;Procurement"],
  "Everpure Germany":["https://www.everpuredata.com/", "Everpure bietet Datenspeicher und Datenmanagement für Rechenzentren und Cloud-Umgebungen. Die Katalogbezeichnung verweist auf eine regionale Einheit; Produktlinien und Verträge sind bei der konkreten Gesellschaft zu prüfen. Käufer sollten Latenz, Kapazitätswachstum, Ausfallsicherheit, Datenmobilität und Wiederherstellung gegen reale Workloads testen. Ein hoher nomineller Durchsatz allein sagt wenig über gemischte Anwendungen und Betriebskosten aus.", "Everpure offers storage and data management for data centres and cloud environments. The catalogue name identifies a regional entity; product lines and contracts need verification for the actual supplier. Buyers should test latency, capacity growth, resilience, data mobility and recovery against real workloads. High nominal throughput alone says little about mixed applications or operating cost.", "Enterprise Storage;Flash;Datenplattform;Resilienz;Kapazität;Hybrid Cloud;Recovery", "Enterprise storage;Flash;Data platform;Resilience;Capacity;Hybrid cloud;Recovery", "Rechenzentrum;Storage;CIO;Cloud;Backup;IT-Betrieb;Einkauf", "Data centres;Storage;CIO;Cloud;Backup;IT operations;Procurement"],
  "Box":["https://www.box.com/", "Box bietet eine Cloud-Plattform für Zusammenarbeit und Verwaltung von Unternehmensinhalten. Freigaben, Workflows und Integrationen verbinden Dokumente mit Fachprozessen, deren Berechtigungen konsistent bleiben müssen. Käufer sollten externe Zusammenarbeit, Datenstandorte, Aufbewahrung, Versionskontrolle und API-Zugriffe anhand typischer Dokumente testen. KI-Auswertung von Inhalten benötigt zusätzlich Regeln für vertrauliche Daten und die Prüfung erzeugter Antworten.", "Box provides a cloud platform for collaboration and enterprise content management. Sharing, workflows and integrations connect documents to business processes, whose permissions must remain consistent. Buyers should test external collaboration, data locations, retention, version control and API access with representative documents. AI analysis of content additionally needs rules for confidential information and verification of generated answers.", "Content Cloud;Dateifreigabe;Workflows;Governance;Integrationen;KI-Suche;Zusammenarbeit", "Content cloud;File sharing;Workflows;Governance;Integrations;AI search;Collaboration", "IT;Wissensmanagement;Datenschutz;Compliance;Fachbereiche;Sicherheit;Einkauf", "IT;Knowledge management;Privacy;Compliance;Business units;Security;Procurement"],
  "Checkmarx Germany":["https://checkmarx.com/", "Checkmarx bietet Sicherheitsprüfung für Anwendungscode und Software-Lieferketten. Unterschiedliche Scanverfahren erkennen unterschiedliche Risikoklassen; Ergebnisse müssen in Entwicklung und Freigaben bearbeitbar sein. Käufer sollten Sprachabdeckung, Falschalarme, CI/CD-Einbindung, Regeln und Maßnahmenverfolgung an eigenen Repositories testen. Eine erfolgreiche Analyse ist keine Garantie für fehlerfreien Code oder sichere produktive Konfiguration.", "Checkmarx provides security testing for application code and software supply chains. Different scanning approaches detect different risk classes; findings need actionable handling in development and release. Buyers should test language support, false positives, CI/CD integration, policies and remediation tracking on their own repositories. A successful scan cannot guarantee defect-free code or secure production configuration.", "SAST;Software Composition;AppSec;CI/CD;API-Sicherheit;Priorisierung;Developer Workflows", "SAST;Software composition;AppSec;CI/CD;API security;Prioritisation;Developer workflows", "CISO;AppSec;Entwicklung;DevOps;Architektur;Compliance;IT-Einkauf", "CISO;AppSec;Development;DevOps;Architecture;Compliance;IT procurement"],
  "Freshworks":["https://www.freshworks.com/", "Freshworks bietet Cloud-Software für Kundenservice, IT-Service und weitere Geschäftsprozesse. Ticketing, Automatisierung und Self-Service müssen zur Organisation der Service-Teams und zu vorhandenen Kanälen passen. Käufer sollten Routing, Datenmigration, SLA-Logik, Rollen und Integrationen anhand echter Fälle prüfen. KI-Assistenten können Vorschläge machen, benötigen aber überprüfbare Antworten und klare Übergaben an Menschen.", "Freshworks offers cloud software for customer support, IT service and other business processes. Ticketing, automation and self-service need to fit service teams and existing channels. Buyers should test routing, data migration, SLA rules, roles and integrations using real cases. AI assistants can suggest responses, but need verifiable answers and clear handovers to people.", "Customer Service;ITSM;Ticketing;Automatisierung;Self-Service;KI-Assistenten;Reporting", "Customer service;ITSM;Ticketing;Automation;Self-service;AI assistants;Reporting", "Customer Support;IT-Service;CIO;Operations;Datenschutz;Service Design;Einkauf", "Customer support;IT service;CIO;Operations;Privacy;Service design;Procurement"],
  "Genetec Deutschland":["https://www.genetec.com/", "Genetec entwickelt Plattformen für physische Sicherheit, darunter Videoüberwachung, Zutrittskontrolle und Kennzeichenerfassung. Die Module müssen mit Kameras, Türen, Netz und organisatorischen Regeln zusammenpassen. Käufer sollten Integrationen, Speicherdauer, Berechtigungen, Ausfallszenarien und Datenschutz für jeden Standort prüfen. Videoanalyse und Zutrittsereignisse sind sensible Daten; ein technisch möglicher Einsatz ist nicht automatisch rechtlich oder organisatorisch angemessen.", "Genetec develops physical security platforms including video surveillance, access control and licence-plate recognition. Modules need to fit cameras, doors, networks and organisational rules. Buyers should evaluate integrations, retention, permissions, outage scenarios and privacy for each location. Video analytics and access events involve sensitive data; technical feasibility does not automatically establish lawful or proportionate use.", "Video Management;Zutrittskontrolle;Kennzeichenerfassung;Sicherheitsplattform;Integration;Monitoring;Datenschutz", "Video management;Access control;Licence-plate recognition;Security platform;Integration;Monitoring;Privacy", "Physische Sicherheit;Facility;IT;Datenschutz;CISO;Standortleitung;Einkauf", "Physical security;Facilities;IT;Privacy;CISO;Site management;Procurement"],
  "Versa Networks":["https://versa-networks.com/", "Versa Networks bietet Netzwerk- und Sicherheitssoftware für SD-WAN und SASE. Organisationen verbinden Standorte und Nutzerzugriffe unter gemeinsamen Richtlinien, müssen aber den Datenweg je Anwendung verstehen. Käufer sollten Latenz, PoP-Abdeckung, Identitätsintegration, Administration, Ausfallsicherheit und Protokollierung im eigenen Netz testen. Souveränitätsaussagen erfordern eine Prüfung von Kontroll- und Datenebene sowie vertraglichem Betrieb.", "Versa Networks provides networking and security software for SD-WAN and SASE. Organisations connect sites and user access under shared policies, while still needing to understand each application's data path. Buyers should test latency, PoP coverage, identity integration, administration, resilience and logging in their network. Sovereignty claims require review of control and data planes and contracted operations.", "SD-WAN;SASE;Zero Trust;Netzwerksicherheit;Standortvernetzung;Policies;Cloud-Zugriff", "SD-WAN;SASE;Zero Trust;Network security;Site networking;Policies;Cloud access", "CISO;Netzwerk;Cloud;IT-Betrieb;Architektur;Datenschutz;Einkauf", "CISO;Networking;Cloud;IT operations;Architecture;Privacy;Procurement"],
  "Asahi Kasei Europe":["https://asahi-kasei.eu/", "Asahi Kasei Europe repräsentiert ein breites Material- und Technologieportfolio des Konzerns für industrielle Anwendungen. Werkstoffe, Elektronik und weitere Produktgruppen haben unterschiedliche Spezifikationen und Lieferketten. Käufer sollten das konkrete Material mit Sicherheitsdatenblatt, Zulassung, Lebensdauer und Verarbeitungsprozess abgleichen. Forschungsnachrichten über Batterietechnik belegen keine Verfügbarkeit oder Leistung eines einzelnen Materials in Serienfertigung.", "Asahi Kasei Europe represents a broad group portfolio of materials and technologies for industrial applications. Materials, electronics and other product groups have different specifications and supply chains. Buyers should match the specific material to safety data, approvals, lifetime and processing conditions. Research announcements on batteries do not prove availability or performance of an individual material in volume production.", "Werkstoffe;Chemie;Elektronik;Batteriematerialien;Forschung;Industrieanwendungen;Lieferkette", "Materials;Chemicals;Electronics;Battery materials;Research;Industrial applications;Supply chain", "Forschung;Entwicklung;Produktion;Qualität;Nachhaltigkeit;Technischer Einkauf;Regulierung", "Research;Development;Manufacturing;Quality;Sustainability;Technical procurement;Regulatory"],
  "BlackLine":["https://www.blackline.com/", "BlackLine bietet Software zur Automatisierung von Finanzabschluss und Accounting-Prozessen. Abstimmungen, Buchungen und Nachweise können über kontrollierte Workflows zusammenlaufen, müssen aber an ERP und interne Kontrollsysteme angepasst werden. Käufer sollten Datenqualität, Rechte, Freigaben, Audit-Trail und Ausnahmebehandlung an einem echten Monatsabschluss testen. KI-Vorschläge benötigen nachvollziehbare Regeln und verantwortliche Freigabe durch das Finanzteam.", "BlackLine provides software to automate financial close and accounting processes. Reconciliations, journal entries and evidence can flow through controlled workflows, but must align with ERP and internal controls. Buyers should test data quality, permissions, approvals, audit trail and exception handling against a real monthly close. AI suggestions require explainable rules and accountable sign-off by finance teams.", "Finanzabschluss;Kontenabstimmung;Buchungen;Audit-Trail;ERP-Integration;Kontrollen;Automatisierung", "Financial close;Reconciliation;Journal entries;Audit trail;ERP integration;Controls;Automation", "CFO;Accounting;Controlling;Revision;ERP;Compliance;Einkauf", "CFO;Accounting;Controlling;Internal audit;ERP;Compliance;Procurement"],
  "Databricks":["https://www.databricks.com/", "Databricks verbindet Datenverarbeitung, Analytik und KI-Entwicklung auf einer Datenplattform. Lakehouse-Architektur und Governance sollen Daten für mehrere Teams nutzbar machen; konkrete Leistung hängt von Cloud, Workloads und Datenmodell ab. Käufer sollten Kosten, Rechte, Datenherkunft, Performance und Modellbetrieb anhand realer Pipelines prüfen. Eine gemeinsame Plattform ersetzt keine fachlichen Definitionen oder die verantwortliche Prüfung von KI-Ergebnissen.", "Databricks combines data processing, analytics and AI development on a data platform. Lakehouse architecture and governance aim to make data usable across teams; actual performance depends on cloud, workloads and data models. Buyers should test cost, permissions, lineage, performance and model operations using real pipelines. One platform does not replace business definitions or accountable review of AI outputs.", "Lakehouse;Data Engineering;Analytics;ML;Governance;Pipelines;KI-Betrieb", "Lakehouse;Data engineering;Analytics;ML;Governance;Pipelines;AI operations", "CIO;Data Engineering;BI;Data Science;CISO;FinOps;Einkauf", "CIO;Data engineering;BI;Data science;CISO;FinOps;Procurement"],
  "Panasonic Connect Europe":["https://eu.connect.panasonic.com/gb/en", "Panasonic Connect Europe liefert professionelle Geräte und Lösungen für mobile Arbeit, Kommunikation und Industrie. TOUGHBOOK adressiert robuste Endgeräte; weitere Geschäftsbereiche folgen anderen Anforderungen. Käufer sollten die jeweilige Produktlinie, Funktechnik, Service, Zubehör und Integration in Unternehmenssoftware einzeln prüfen. Eine Referenz aus kritischer Infrastruktur ist kein Eignungsnachweis für jede Netz- und Einsatzumgebung.", "Panasonic Connect Europe supplies professional devices and solutions for mobile work, communications and industry. TOUGHBOOK addresses rugged endpoints; other business areas have different requirements. Buyers should assess each product line, radio technology, service, accessories and enterprise software integration separately. A critical-infrastructure reference cannot establish suitability for every network and operating environment.", "TOUGHBOOK;Rugged Devices;Mobiles Arbeiten;Private 5G;Industriegeräte;Service;Integration", "TOUGHBOOK;Rugged devices;Mobile work;Private 5G;Industrial devices;Service;Integration", "Außendienst;IT;Industrie;Öffentliche Sicherheit;Netzwerk;Service;Einkauf", "Field service;IT;Industry;Public safety;Networking;Support;Procurement"],
  "Scality":["https://www.scality.com/", "Scality entwickelt Software für Objekt- und Dateispeicherung in Unternehmensumgebungen. Einsatzfelder reichen von großen Datenbeständen bis zu Backup-Zielen, wobei Datenzugriff und Wiederherstellung unterschiedlich zu planen sind. Käufer sollten S3-Kompatibilität, Skalierung, Replikation, Hardwareanforderungen und Betrieb anhand vorhandener Workloads testen. Objektspeicher ersetzt nicht automatisch Block-Storage oder einen vollständigen Wiederanlaufplan.", "Scality develops software for object and file storage in enterprise environments. Use cases range from large data estates to backup targets, with differing access and recovery needs. Buyers should test S3 compatibility, scaling, replication, hardware requirements and operations against existing workloads. Object storage does not automatically replace block storage or a full business recovery plan.", "Objektspeicher;S3;Dateispeicher;Skalierung;Backup-Ziel;Replikation;Datenschutz", "Object storage;S3;File storage;Scaling;Backup target;Replication;Data protection", "Storage;Rechenzentrum;Backup;Cloud-Architektur;IT-Betrieb;Sicherheit;Einkauf", "Storage;Data centres;Backup;Cloud architecture;IT operations;Security;Procurement"],
  "Claroty":["https://claroty.com/", "Claroty bietet Lösungen zur Sichtbarkeit und Absicherung vernetzter OT- und medizinischer Geräte. Inventarisierung, Risikoanalyse und Zugriffsschutz müssen auf Produktions- oder Klinikabläufe abgestimmt werden. Käufer sollten passive Erfassung, Geräteklassifikation, Integrationen, Wartungsfenster und Reaktion auf Befunde prüfen. In sensiblen Netzen darf eine Sicherheitsmaßnahme die Verfügbarkeit der Anlage oder Patientenversorgung nicht ungewollt gefährden.", "Claroty provides visibility and security for connected operational and medical devices. Inventory, risk analysis and access protection must fit industrial or clinical operations. Buyers should test passive discovery, device classification, integration, maintenance windows and response to findings. In sensitive networks, a security measure must not inadvertently disrupt plant availability or patient care.", "OT-Sicherheit;Geräteinventar;Medizinische Geräte;Risikoanalyse;Zugriff;Netzwerktransparenz;Monitoring", "OT security;Device inventory;Medical devices;Risk analysis;Access;Network visibility;Monitoring", "OT;CISO;Werksleitung;Medizintechnik;IT-Betrieb;Risiko;Einkauf", "OT;CISO;Plant management;Biomedical engineering;IT operations;Risk;Procurement"],
  "KYOCERA Europe":["https://www.kyoceradocumentsolutions.eu/", "KYOCERA Europe bündelt unterschiedliche Geschäftsbereiche; die zugeordneten Bürothemen betreffen insbesondere Druck- und Dokumentenlösungen. Unternehmen sollten Geräte, Verbrauchsmaterial, Software und Serviceverträge getrennt prüfen. Für die Auswahl zählen Druckvolumen, Datenschutz, Fernwartung, Energiebedarf und Integration in digitale Workflows. Aussagen einer europäischen Einheit oder Produktgruppe dürfen nicht pauschal allen KYOCERA-Gesellschaften zugeschrieben werden.", "KYOCERA Europe spans different businesses; the office-related material in this catalogue chiefly concerns printing and document solutions. Organisations should assess devices, consumables, software and service contracts separately. Selection depends on print volume, privacy, remote maintenance, energy demand and digital-workflow integration. Claims by a European entity or one product group should not be attributed to all KYOCERA companies.", "Drucksysteme;Dokumentenworkflows;Multifunktionsgeräte;Service;Verbrauchsmaterial;Sicherheit;Energie", "Printing systems;Document workflows;Multifunction devices;Service;Consumables;Security;Energy", "IT;Office Management;Facility;Datenschutz;Einkauf;Nachhaltigkeit;Service Desk", "IT;Office management;Facilities;Privacy;Procurement;Sustainability;Service desk"],
  "Quadient":["https://www.quadient.com/", "Quadient bietet Lösungen für Kundenkommunikation, Dokumentenprozesse und angrenzende Geschäftsabläufe. Digitale und physische Zustellung sowie Automatisierung brauchen konsistente Kundendaten und abgestimmte Freigaben. Käufer sollten Kanäle, Vorlagen, Archivierung, Barrierefreiheit, Integration und Nachweisbarkeit prüfen. Eine beschleunigte Dokumentenerstellung ist kein Beleg für korrekte Inhalte; regulatorisch relevante Kommunikation erfordert fachliche Verantwortung.", "Quadient offers solutions for customer communication, document processes and related business operations. Digital and physical delivery and automation require consistent customer data and coordinated approval. Buyers should review channels, templates, retention, accessibility, integration and evidence of delivery. Faster document creation cannot prove content accuracy; regulated communications require accountable business review.", "Customer Communications;Dokumente;Omnichannel;Automatisierung;Versand;Vorlagen;Integration", "Customer communications;Documents;Omnichannel;Automation;Delivery;Templates;Integration", "Kundenservice;Marketing;Operations;Compliance;IT;Datenschutz;Einkauf", "Customer service;Marketing;Operations;Compliance;IT;Privacy;Procurement"],
  "Flexera Software":["https://www.flexera.com/", "Flexera bietet Lösungen für IT-Asset-Management, Softwarelizenzen und Cloud-Kosten. Daten aus Inventar, Verträgen und Nutzung müssen zusammengeführt werden, bevor belastbare Optimierungen möglich sind. Käufer sollten Erkennungsgenauigkeit, Lizenzregeln, Cloud-Konten, Berichtsfunktionen und Prozesse für Ausnahmen testen. Ein automatisierter Lizenzabgleich ersetzt keine vertragliche Prüfung der konkreten Nutzungsrechte.", "Flexera offers IT asset management, software licensing and cloud cost solutions. Inventory, contracts and usage data must be reconciled before meaningful optimisation. Buyers should test discovery accuracy, licence rules, cloud accounts, reporting and exception processes. Automated licence reconciliation does not replace contractual review of actual usage rights.", "ITAM;Software Asset Management;Cloud-Kosten;Lizenzmanagement;Inventar;FinOps;Compliance", "ITAM;Software asset management;Cloud costs;Licence management;Inventory;FinOps;Compliance", "CIO;ITAM;FinOps;Einkauf;Compliance;Cloud;Finanzen", "CIO;ITAM;FinOps;Procurement;Compliance;Cloud;Finance"],
  "Keeper Security":["https://www.keepersecurity.com/", "Keeper Security bietet Passwort- und Geheimnisverwaltung für Unternehmen. Lösungen für Beschäftigte und privilegierte Zugänge müssen in Identitätsprozesse, Geräte und Freigaben eingebunden werden. Käufer sollten SSO, Provisionierung, Wiederherstellung, Audit, geteilte Tresore und Notfallzugriff testen. Ein Passwortmanager hilft gegen Wiederverwendung, kann Phishing, kompromittierte Endgeräte und unzureichende Rollenmodelle jedoch nicht allein beheben.", "Keeper Security provides password and secrets management for organisations. Employee and privileged access tools must integrate with identity processes, devices and approvals. Buyers should test SSO, provisioning, recovery, audit, shared vaults and emergency access. A password manager helps prevent password reuse but cannot by itself resolve phishing, compromised endpoints or weak role models.", "Passwortmanagement;Secrets;Privilegierte Zugänge;SSO;Tresore;Audit;Notfallzugriff", "Password management;Secrets;Privileged access;SSO;Vaults;Audit;Emergency access", "CISO;IAM;IT-Betrieb;Compliance;Service Desk;Datenschutz;Einkauf", "CISO;IAM;IT operations;Compliance;Service desk;Privacy;Procurement"],
  "Snowflake Computing":["https://www.snowflake.com/en/", "Snowflake bietet eine Cloud-Datenplattform für Speicherung, Verarbeitung, gemeinsame Nutzung und Analyse von Daten. Nutzungskosten und Datenbewegungen hängen von Workloads, Architektur und Freigaben ab. Käufer sollten Rollen, Datenherkunft, Schnittstellen, Regionen, Leistung und Ausgabensteuerung an repräsentativen Abfragen testen. Der Austausch von Daten zwischen Organisationen benötigt klare Nutzungsrechte; eine Plattform allein gewährleistet keine konsistenten Kennzahlen.", "Snowflake offers a cloud data platform for storage, processing, sharing and analysis. Consumption cost and data movement depend on workloads, architecture and access rules. Buyers should test roles, lineage, interfaces, regions, performance and spend controls using representative queries. Sharing data between organisations needs clear usage rights; a platform alone cannot ensure consistent business metrics.", "Data Cloud;Warehouse;Data Sharing;Analytics;Governance;Compute;Integration", "Data cloud;Warehouse;Data sharing;Analytics;Governance;Compute;Integration", "Datenleitung;BI;IT-Architektur;FinOps;Compliance;Data Engineering;Einkauf", "Data leadership;BI;IT architecture;FinOps;Compliance;Data engineering;Procurement"],
  "audius":["https://www.audius.de/", "audius entwickelt und integriert Software für Geschäftsprozesse, Kundenmanagement und industrielle Anwendungen. Produkte, Entwicklung und Beratung haben je Projekt verschiedene Zuständigkeiten. Käufer sollten Branchenfunktionen, Schnittstellen, Migration, Datenschutz und Betrieb anhand eigener Prozesse prüfen. Ein Implementierungsprojekt kann Partnerprodukte umfassen; Vertragsumfang und spätere Wartung sollten vor Einführung ausdrücklich feststehen.", "audius develops and integrates software for business processes, customer management and industrial applications. Products, development and consulting carry different responsibilities by project. Buyers should assess industry functions, interfaces, migration, privacy and operations using their own processes. An implementation may involve partner products; contracted scope and subsequent maintenance should be explicit before rollout.", "CRM;Geschäftssoftware;Integration;Industrie;Beratung;Entwicklung;Betrieb", "CRM;Business software;Integration;Industry;Consulting;Development;Operations", "CIO;CRM;Vertrieb;Produktion;IT-Architektur;Datenschutz;Einkauf", "CIO;CRM;Sales;Production;IT architecture;Privacy;Procurement"],
  "Cornerstone OnDemand Germany":["https://www.cornerstoneondemand.com/", "Cornerstone bietet Software für Lernen, Talentmanagement und Mitarbeiterentwicklung. Unternehmen verbinden Lerninhalte, Rollen und Qualifizierungsziele mit Personalprozessen und Berechtigungen. Käufer sollten Inhaltsrechte, Mehrsprachigkeit, Integrationen, Lernnachweise und Nutzbarkeit für verschiedene Beschäftigtengruppen prüfen. Ein absolvierter Kurs beweist noch keine praktische Kompetenz; Lernerfolg und betriebliche Wirkung brauchen eigene Maßstäbe.", "Cornerstone provides software for learning, talent management and workforce development. Organisations connect content, roles and skills goals with HR processes and permissions. Buyers should assess content rights, languages, integrations, learning evidence and usability across employee groups. Completion of a course does not by itself prove applied competence; learning outcomes and business impact need separate measures.", "Learning Management;Skills;Talent;Lerninhalte;HR-Integration;Analytik;Compliance-Schulung", "Learning management;Skills;Talent;Learning content;HR integration;Analytics;Compliance training", "HR;Learning & Development;IT;Compliance;Fachbereiche;Betriebsrat;Einkauf", "HR;Learning and development;IT;Compliance;Business units;Works council;Procurement"],
  "STARFACE":["https://www.starface.com/", "STARFACE bietet Unternehmenskommunikation mit Telefonie, Unified Communications und Integrationsmöglichkeiten. Bereitstellung und Funktionsumfang hängen von Plattform, Endgeräten und Anbindungen ab. Käufer sollten Rufnummernportierung, Ausfallsicherheit, Präsenz, Mobilnutzung und Datenschutz bei Aufzeichnungen testen. Eine neue Telefonanlage muss auch Notrufe und bestehende Arbeitsabläufe abdecken; die Migration sollte mit konkreten Standorten geplant werden.", "STARFACE provides business communications with telephony, unified communications and integrations. Deployment and feature scope depend on platform, devices and connectivity. Buyers should test number porting, resilience, presence, mobile use and recording privacy. A new phone system must also support emergency calling and existing workflows; migration should be planned for each site.", "Telefonie;UC;Cloud-PBX;Integration;Mobile Clients;Kontaktcenter;Betrieb", "Telephony;UC;Cloud PBX;Integration;Mobile clients;Contact centre;Operations", "IT;Kommunikation;Service Desk;Standortleitung;Datenschutz;Kundenservice;Einkauf", "IT;Communications;Service desk;Site management;Privacy;Customer service;Procurement"],
  "Westcon Group Germany":["https://www.westconcomstor.com/", "Westcon Group Germany ist Teil eines Technologievertriebs mit Fokus auf Hersteller- und Partnerökosysteme. Distribution, Enablement und Services unterscheiden sich vom Produkt und Support des jeweiligen Herstellers. Reseller sollten Verfügbarkeit, Lizenzlaufzeiten, Partnerstatus, technische Unterstützung und Eskalationswege je Angebot prüfen. Ein Portfolioeintrag bedeutet weder exklusiven Vertrieb noch eine direkte Herstellergarantie durch den Distributor.", "Westcon Group Germany is part of a technology distributor focused on vendor and partner ecosystems. Distribution, enablement and services differ from each vendor's own products and support. Resellers should assess availability, licence terms, partner status, technical assistance and escalation by offer. A portfolio listing does not imply exclusive distribution or a direct vendor warranty from the distributor.", "IT-Distribution;Channel;Cloud-Lizenzen;Security;Netzwerke;Enablement;Services", "IT distribution;Channel;Cloud licences;Security;Networking;Enablement;Services", "Reseller;Systemhäuser;Channel Sales;Technik;Lizenzmanagement;Einkauf;Partnerleitung", "Resellers;Systems integrators;Channel sales;Engineering;Licence management;Procurement;Partner leadership"],
  "Core Technologie":["https://coretechnologie.com/", "Core Technologie entwickelt Software für CAD-Datenkonvertierung, Modellprüfung und industrielle 3D-Prozesse. Engineering-Teams können Formate austauschen und Geometrien für nachgelagerte Anwendungen vorbereiten. Käufer sollten native Formatunterstützung, Modelltreue, Automatisierung und Versionen mit eigenen Bauteilen prüfen. Ein konvertiertes Modell benötigt weiterhin fachliche Freigabe, insbesondere wenn Toleranzen und Fertigungsinformationen relevant sind.", "Core Technologie develops software for CAD data conversion, model validation and industrial 3D processes. Engineering teams can exchange formats and prepare geometry for downstream applications. Buyers should test native format support, model fidelity, automation and versions using their own parts. A converted model still needs engineering approval, particularly where tolerances and manufacturing information matter.", "CAD-Konvertierung;3D-Daten;Modellprüfung;Geometrie;Automatisierung;Engineering;Interoperabilität", "CAD conversion;3D data;Model validation;Geometry;Automation;Engineering;Interoperability", "Konstruktion;PLM;Fertigung;Qualität;IT;Zulieferer;Einkauf", "Design engineering;PLM;Manufacturing;Quality;IT;Suppliers;Procurement"],
  "Cristie Data":["https://cristie.de/", "Cristie Data bietet Backup, Archivierung und Cyber-Recovery für Unternehmen. Eigene Dienstleistungen und eingesetzte Partnertechnologien müssen nach Vertrag und Umgebung unterschieden werden. Käufer sollten Sicherungsumfang, Unveränderbarkeit, Restore-Zeiten, Mandantenrechte und laufende Betreuung prüfen. Eine gesicherte Datei ist noch kein funktionierender Dienst; Wiederanlaufproben sollten Anwendungen und Abhängigkeiten einschließen.", "Cristie Data provides backup, archiving and cyber recovery for enterprises. Its services and underlying partner technologies should be separated by contract and environment. Buyers should assess protection scope, immutability, restore times, tenant permissions and operational support. A backed-up file is not a working service; recovery drills should include applications and dependencies.", "Backup;Archivierung;Cyber-Recovery;Managed Services;Cloud-Schutz;Restore;Resilienz", "Backup;Archiving;Cyber recovery;Managed services;Cloud protection;Restore;Resilience", "Backup;CISO;IT-Betrieb;Compliance;Cloud;Business Continuity;Einkauf", "Backup;CISO;IT operations;Compliance;Cloud;Business continuity;Procurement"],
  "Darda":["https://www.darda.de/", "Darda liefert hydraulische Abbruchtechnik für Bau, Rückbau und industrielle Einsatzbereiche. Produktwahl hängt von Material, verfügbarem Raum, Trägergerät und Sicherheitsvorgaben ab. Käufer sollten Kraft, Werkzeugwechsel, Wartung, Ersatzteile und den Ablauf auf der Baustelle prüfen. Technische Leistungsdaten aus einem Einsatzbeispiel übertragen sich nicht ohne Prüfung auf andere Bauteile oder Einsatzbedingungen.", "Darda supplies hydraulic demolition equipment for construction, dismantling and industrial work. Product selection depends on material, available space, carrier equipment and safety rules. Buyers should assess force, tool changes, maintenance, spare parts and site procedures. Technical performance in one reference cannot be applied to other structures or operating conditions without review.", "Abbruchtechnik;Hydraulik;Betonbearbeitung;Rückbau;Werkzeuge;Wartung;Sicherheit", "Demolition equipment;Hydraulics;Concrete work;Dismantling;Tools;Maintenance;Safety", "Bauleitung;Rückbau;Arbeitsschutz;Maschinenpark;Technik;Service;Einkauf", "Construction management;Demolition;Safety;Plant fleet;Engineering;Service;Procurement"],
  "Emporix":["https://www.emporix.com/", "Emporix entwickelt eine Commerce-Plattform für komplexe Handelsprozesse und digitale Vertriebskanäle. APIs und modulare Funktionen müssen an Preislogik, Produktdaten und vorhandene ERP-Systeme angebunden werden. Käufer sollten B2B-Rollen, Bestellvarianten, Skalierung, Datenfluss und Erweiterbarkeit an realen Warenkörben testen. Ein Composable-Ansatz senkt nicht automatisch Integrationsaufwand oder Betriebskosten.", "Emporix develops a commerce platform for complex trading processes and digital sales channels. APIs and modular functions need connecting to pricing, product data and existing ERP systems. Buyers should test B2B roles, order variants, scaling, data flows and extensibility with real carts. A composable approach does not automatically reduce integration effort or operating cost.", "B2B-Commerce;APIs;Bestellungen;Preislogik;ERP-Integration;Composable Commerce;Kataloge", "B2B commerce;APIs;Orders;Pricing;ERP integration;Composable commerce;Catalogues", "E-Commerce;Vertrieb;Produktmanagement;IT;ERP;Architektur;Einkauf", "E-commerce;Sales;Product management;IT;ERP;Architecture;Procurement"],
  "enclaive":["https://enclaive.io/", "enclaive bietet Ansätze für Confidential Computing und geschützte Verarbeitung von Daten in Cloud-Umgebungen. Technische Abschirmung hängt von Hardware, Attestierung, Schlüsselverwaltung und tatsächlichem Anwendungsdesign ab. Käufer sollten Bedrohungsmodell, Integrationen, Betrieb und Leistungsfolgen anhand sensibler Workloads prüfen. Vertrauliche Ausführung ersetzt keine Zugriffskontrolle, Datenminimierung oder vertragliche Klärung der Datenverarbeitung.", "enclaive offers confidential-computing approaches for protected data processing in cloud environments. Technical isolation depends on hardware, attestation, key management and application design. Buyers should test threat models, integrations, operations and performance effects with sensitive workloads. Confidential execution does not replace access controls, data minimisation or contractual clarification of processing.", "Confidential Computing;Verschlüsselung;Attestierung;Cloud Security;Schlüssel;Datenschutz;Workloads", "Confidential computing;Encryption;Attestation;Cloud security;Keys;Privacy;Workloads", "CISO;Cloud-Architektur;Datenschutz;Entwicklung;Compliance;Infrastruktur;Einkauf", "CISO;Cloud architecture;Privacy;Development;Compliance;Infrastructure;Procurement"],
  "Fivetran":["https://www.fivetran.com/", "Fivetran bietet verwaltete Datenpipelines zwischen operativen Quellen und Analyseplattformen. Konnektoren reduzieren Eigenentwicklung, doch Schemaänderungen, Aktualisierungsintervalle und Kosten bleiben zu steuern. Käufer sollten Quellabdeckung, inkrementelle Übertragung, Löschungen, Berechtigungen und Datenstandorte testen. Eine erfolgreiche Synchronisierung stellt noch keine korrekte fachliche Metrik oder geprüfte Datenherkunft sicher.", "Fivetran provides managed data pipelines between operational sources and analytics platforms. Connectors reduce custom development, but schema changes, refresh intervals and costs still need management. Buyers should test source coverage, incremental transfer, deletions, permissions and data locations. Successful synchronisation does not establish correct business metrics or verified data lineage.", "Datenpipelines;Konnektoren;ELT;Schemaänderungen;Warehouse;Datenintegration;Monitoring", "Data pipelines;Connectors;ELT;Schema changes;Warehouse;Data integration;Monitoring", "Data Engineering;BI;IT;Datenschutz;FinOps;Analytics;Einkauf", "Data engineering;BI;IT;Privacy;FinOps;Analytics;Procurement"],
  "HUK-COBURG":["https://www.huk.de/produkte-fuer-unternehmen.html", "HUK-COBURG bietet Versicherungsprodukte, deren Einsatz für Unternehmen von Sparte und Tarif abhängt. Deckung, Ausschlüsse und Schadenbearbeitung müssen für den konkreten Bedarf geprüft werden. Käufer sollten Risiken, Selbstbehalte, Geltungsräume, Laufzeiten und Servicewege vergleichen. Allgemeine Ratgeber oder Unternehmensmeldungen sind keine Zusage, dass ein bestimmter Schaden versichert ist.", "HUK-COBURG offers insurance products whose business suitability depends on line and policy. Coverage, exclusions and claims handling need review for the specific requirement. Buyers should compare risks, deductibles, territories, terms and service channels. General advice or company announcements do not guarantee cover for a particular loss.", "Versicherung;Gewerberisiken;Schadenservice;Tarife;Haftung;Vertragsprüfung;Prävention", "Insurance;Business risks;Claims service;Policies;Liability;Contract review;Prevention", "Geschäftsführung;Risk;Finanzen;Recht;Fuhrpark;HR;Einkauf", "Management;Risk;Finance;Legal;Fleet;HR;Procurement"],
  "IBM":["https://www.ibm.com/products", "IBM bietet Software, Infrastruktur und Beratung für Unternehmen. Hybrid Cloud, Daten, Automatisierung und KI sind getrennte Angebotsbereiche mit teils unterschiedlichen Vertragsparteien und Partnern. Käufer sollten Architektur, Integrationen, Datenrechte, Betrieb, Migration und Lizenzkosten je Produkt prüfen. Ein Modell oder eine Referenz für eine Branche belegt nicht automatisch die Leistung einer anderen IBM-Konfiguration.", "IBM provides enterprise software, infrastructure and consulting. Hybrid cloud, data, automation and AI are distinct areas, sometimes involving different contracting parties and partners. Buyers should assess architecture, integrations, data rights, operations, migration and licence cost by product. A model or sector reference cannot automatically establish performance for a different IBM configuration.", "Hybrid Cloud;watsonx;Automatisierung;Mainframe;Datenplattform;Beratung;Security", "Hybrid cloud;watsonx;Automation;Mainframe;Data platform;Consulting;Security", "CIO;Architektur;Datenleitung;KI;IT-Betrieb;CISO;Einkauf", "CIO;Architecture;Data leadership;AI;IT operations;CISO;Procurement"],
  "simus systems":["https://www.simus-systems.com/", "simus systems entwickelt Software zur Strukturierung technischer Daten und zur Unterstützung von Konstruktionsprozessen. Klassifikation und Wiederverwendung von Bauteilen können Suchaufwand senken, benötigen jedoch gepflegte Merkmale und verlässliche CAD- und ERP-Anbindung. Käufer sollten Datenqualität, Dubletten, Sprachvarianten und Berechtigungen mit eigenen Teilebeständen testen. Automatische Klassifizierung braucht fachliche Kontrolle.", "simus systems develops software to structure technical data and support engineering processes. Classification and component reuse can reduce search effort but require maintained attributes and reliable CAD and ERP integration. Buyers should test data quality, duplicates, language variants and permissions using their own parts. Automated classification needs expert validation.", "Bauteilklassifikation;CAD-Daten;Dubletten;Teilewiederverwendung;ERP;Stammdaten;Suche", "Parts classification;CAD data;Duplicates;Parts reuse;ERP;Master data;Search", "Konstruktion;PLM;Einkauf;Stammdaten;IT;Fertigung;Qualität", "Design engineering;PLM;Procurement;Master data;IT;Manufacturing;Quality"],
  "Adobe Systems Europe":["https://www.adobe.com/", "Adobe stellt Werkzeuge für Kreativproduktion, Dokumente und digitale Kundenerlebnisse bereit. Creative Cloud, Acrobat und Experience-Angebote folgen verschiedenen Lizenz- und Datenmodellen; die regionale Katalogeinheit ist von Produktlinien zu unterscheiden. Käufer sollten Rollen, Dateiformate, Integrationen, Rechte und KI-Datenverarbeitung je Anwendung prüfen. Der Einsatz generativer Funktionen erfordert zusätzlich Freigaben für Markenmaterial und Ergebnisqualität.", "Adobe supplies tools for creative production, documents and digital customer experiences. Creative Cloud, Acrobat and Experience offerings have different licensing and data models; the regional catalogue entity differs from individual product lines. Buyers should review roles, file formats, integrations, rights and AI data processing by application. Generative features also require approval processes for brand material and output quality.", "Creative Cloud;Acrobat;Experience Cloud;Dokumente;KI-Werkzeuge;Asset Management;Integration", "Creative Cloud;Acrobat;Experience Cloud;Documents;AI tools;Asset management;Integration", "Marketing;Design;IT;Datenschutz;Recht;Dokumentenmanagement;Einkauf", "Marketing;Design;IT;Privacy;Legal;Document management;Procurement"],
  "Crowdstrike":["https://www.crowdstrike.com/", "CrowdStrike bietet eine Plattform für Endpunktschutz, Bedrohungsanalyse und Sicherheitsbetrieb. Sensoren und Cloud-Dienste müssen mit Geräten, Identitäten und Incident-Prozessen zusammenspielen. Käufer sollten Abdeckung, Erkennungsqualität, Rollout, Datenaufbewahrung und Reaktionswege testen. Auch eine zentrale Sicherheitsplattform benötigt kontrollierte Updates und einen Ausfallplan, damit Schutzmaßnahmen den Betrieb nicht unbeabsichtigt unterbrechen.", "CrowdStrike provides a platform for endpoint protection, threat analysis and security operations. Sensors and cloud services must work with devices, identities and incident processes. Buyers should test coverage, detection quality, rollout, data retention and response paths. A central security platform also needs controlled updates and an outage plan so protection measures do not unexpectedly disrupt operations.", "Endpoint Security;EDR;Threat Intelligence;SOC;Identität;Cloud Security;Incident Response", "Endpoint security;EDR;Threat intelligence;SOC;Identity;Cloud security;Incident response", "CISO;SOC;Endpoint-Betrieb;Cloud;IT-Leitung;Compliance;Einkauf", "CISO;SOC;Endpoint operations;Cloud;IT leadership;Compliance;Procurement"],
  "F5":["https://www.f5.com/", "F5 bietet Technologien für Anwendungsbereitstellung und Anwendungssicherheit. Load Balancing, API-Schutz und WAF adressieren verschiedene Schichten und müssen zu Architektur und Traffic-Mustern passen. Käufer sollten Durchsatz, Policies, Zertifikate, Automatisierung, Ausfallverhalten und Betriebsmodell unter realer Last testen. Eine Schutzregel darf legitime Nutzer nicht blockieren und muss fortlaufend an Anwendungen angepasst werden.", "F5 offers application delivery and application security technologies. Load balancing, API protection and WAF address different layers and must suit architecture and traffic patterns. Buyers should test throughput, policies, certificates, automation, failure behaviour and operating model under realistic load. A protection rule must not block legitimate users and needs ongoing tuning to applications.", "Load Balancing;WAF;API-Sicherheit;App Delivery;DDoS;Traffic Management;Automation", "Load balancing;WAF;API security;App delivery;DDoS;Traffic management;Automation", "App-Betrieb;CISO;Netzwerk;Cloud;DevOps;Architektur;Einkauf", "Application operations;CISO;Networking;Cloud;DevOps;Architecture;Procurement"],
  "Kaspersky":["https://www.kaspersky.com/enterprise-security", "Kaspersky bietet Sicherheitsprodukte für Endpunkte, Netzwerke und industrielle Umgebungen. Produkte, Updates und Support müssen für den konkreten Markt und die eigene Beschaffungspolitik geprüft werden. Käufer sollten Schutzwirkung, Telemetriedaten, Integrationen, Betrieb und Lieferkettenrisiken bewerten. Eine Malware-Erkennung allein deckt weder Identitätsmissbrauch noch die organisatorische Reaktion auf einen Sicherheitsvorfall ab.", "Kaspersky offers security products for endpoints, networks and industrial environments. Products, updates and support need checking for the relevant market and procurement policy. Buyers should assess protection, telemetry data, integrations, operations and supply-chain risks. Malware detection alone cannot address identity misuse or the organisational response to a security incident.", "Endpoint Security;Threat Intelligence;OT-Security;Malware-Schutz;Management;Updates;Monitoring", "Endpoint security;Threat intelligence;OT security;Malware protection;Management;Updates;Monitoring", "CISO;SOC;IT-Betrieb;OT;Datenschutz;Compliance;Einkauf", "CISO;SOC;IT operations;OT;Privacy;Compliance;Procurement"],
  "Nutanix Singapore Pte":["https://www.nutanix.com/products", "Nutanix bietet Infrastruktur-Software für virtualisierte Anwendungen und hybride Cloud-Umgebungen. Die im Katalog genannte Gesellschaft ist eine regionale Einheit; konkrete Vertragsbeziehungen sind zu klären. Käufer sollten Hardwarekompatibilität, Migration, Netz, Speicherkapazität, Lizenzierung und Wiederherstellung testen. Der Wechsel einer Virtualisierungsplattform benötigt einen Plan für Betriebsteams und kritische Altanwendungen.", "Nutanix offers infrastructure software for virtualised applications and hybrid cloud estates. The catalogue names a regional entity; contracting relationships require clarification. Buyers should test hardware compatibility, migration, networking, storage capacity, licensing and recovery. Moving a virtualisation platform requires a plan for operational teams and critical legacy applications.", "Hyperconverged Infrastructure;Virtualisierung;Hybrid Cloud;Storage;Migration;Betrieb;Resilienz", "Hyperconverged infrastructure;Virtualisation;Hybrid cloud;Storage;Migration;Operations;Resilience", "CIO;Rechenzentrum;Virtualisierung;Cloud;IT-Betrieb;Architektur;Einkauf", "CIO;Data centres;Virtualisation;Cloud;IT operations;Architecture;Procurement"],
  "PROFI Engineering Systems":["https://www.profi-ag.de/", "PROFI Engineering Systems unterstützt Unternehmen bei IT-Infrastruktur, Cloud und digitalen Projekten. Beratung, Integration und laufender Betrieb können unterschiedliche Herstellersysteme umfassen. Auftraggeber sollten konkrete Projektverantwortung, Servicezeiten, Datenzugriff und Übergaben anhand ihrer Umgebung vereinbaren. Eine Referenz aus dem öffentlichen Sektor bestätigt nicht automatisch die Eignung eines Angebots für jede Kommune.", "PROFI Engineering Systems supports organisations with IT infrastructure, cloud and digital projects. Consulting, integration and continuing operations may involve different vendors' systems. Clients should agree specific delivery responsibility, service hours, data access and handovers for their environment. A public-sector reference does not automatically establish suitability for every municipality.", "IT-Infrastruktur;Cloud;Systemintegration;Managed Services;Modernisierung;Beratung;Öffentlicher Sektor", "IT infrastructure;Cloud;Systems integration;Managed services;Modernisation;Consulting;Public sector", "CIO;IT-Betrieb;Cloud;Verwaltung;Architektur;Service Management;Einkauf", "CIO;IT operations;Cloud;Administration;Architecture;Service management;Procurement"],
  "PTA IT-Beratung":["https://www.pta.de/", "PTA IT-Beratung entwickelt und integriert Unternehmenssoftware für unterschiedliche Fachprozesse. Projektteams verbinden Beratung, Entwicklung und Einführung mit vorhandenen Systemen; Verantwortungen für Partnerprodukte bleiben gesondert zu regeln. Käufer sollten Fachmodell, Schnittstellen, Tests, Dokumentation, Betrieb und Wissenstransfer konkret vereinbaren. Ein erfolgreiches Individualprojekt lässt sich nicht ohne Anpassung auf andere Daten- und Prozesslandschaften übertragen.", "PTA IT-Beratung develops and integrates enterprise software for varied business processes. Project teams combine consulting, development and rollout with existing systems; responsibilities for partner products remain separate. Buyers should specify domain models, interfaces, testing, documentation, operations and knowledge transfer. A successful custom project cannot be transferred unchanged to a different data and process landscape.", "IT-Beratung;Softwareentwicklung;Systemintegration;Fachprozesse;Testing;Projektbetrieb;Daten", "IT consulting;Software development;Systems integration;Business processes;Testing;Project operations;Data", "CIO;Fachabteilungen;Architektur;Entwicklung;QA;Operations;Einkauf", "CIO;Business units;Architecture;Development;QA;Operations;Procurement"],
  "Sophos":["https://www.sophos.com/en-us/products", "Sophos bietet Sicherheitsprodukte und Managed Detection für Endpunkte, Netzwerke und Cloud-Umgebungen. Wer Schutz intern betreibt oder als Service bezieht, muss Eskalations- und Reaktionsrechte unterschiedlich regeln. Käufer sollten Sensorabdeckung, Angriffssimulation, Alarmqualität, Datenverarbeitung und Incident-Prozesse testen. Ein Sicherheitsbericht des Herstellers ersetzt keine Prüfung der eigenen Konfiguration oder Wiederherstellungsfähigkeit.", "Sophos offers security products and managed detection across endpoints, networks and cloud environments. Teams operating protection internally or as a service need different escalation and response rights. Buyers should test sensor coverage, attack simulation, alert quality, data processing and incident procedures. A vendor security report does not replace assessment of local configuration or recovery capability.", "Endpoint Security;Firewall;MDR;XDR;Cloud Security;Threat Intelligence;Incident Response", "Endpoint security;Firewall;MDR;XDR;Cloud security;Threat intelligence;Incident response", "CISO;SOC;IT-Betrieb;Netzwerk;Cloud;Compliance;Einkauf", "CISO;SOC;IT operations;Networking;Cloud;Compliance;Procurement"],
  "Samsung Electronics":["https://www.samsung.com/business/", "Samsung Electronics bietet für Unternehmen Mobilgeräte, Displays und weitere Hardware mit Verwaltungs- und Serviceangeboten. Produktlinien unterscheiden sich stark in Lebenszyklus, Sicherheitsfunktionen und Einsatzbedingungen. Käufer sollten MDM, Updates, Reparatur, Geräteverfügbarkeit und Zubehör für die konkrete Flotte prüfen. Eine produktive Bereitstellung benötigt Richtlinien für private Nutzung und Datenlöschung beim Gerätewechsel.", "Samsung Electronics offers business mobile devices, displays and other hardware with management and service options. Product lines differ widely in lifecycle, security features and operating conditions. Buyers should test MDM, updates, repair, availability and accessories for the actual fleet. Productive rollout needs rules for personal use and data wiping during device changes.", "Business Smartphones;Displays;Knox;Gerätemanagement;Hardware;Service;Sicherheit", "Business smartphones;Displays;Knox;Device management;Hardware;Service;Security", "IT;Mobility;Einkauf;Informationssicherheit;Facility;HR;Service Desk", "IT;Mobility;Procurement;Information security;Facilities;HR;Service desk"],
  "FIS Informationssysteme und Consulting":["https://www.fis-gmbh.de/en/", "FIS entwickelt und implementiert Lösungen für SAP-nahe Geschäftsprozesse, insbesondere in Handel und Industrie. Eigene Erweiterungen, SAP-Standard und Projektleistungen sollten in Angebot und Betrieb getrennt betrachtet werden. Käufer sollten Stammdaten, Integrationen, Migration, Upgradefähigkeit und Verantwortlichkeit für Anpassungen testen. Eine Branchenreferenz belegt keinen identischen Prozessfit im eigenen ERP-System.", "FIS develops and implements solutions for SAP-related business processes, particularly in trade and industry. Proprietary extensions, SAP standard functionality and project services should be assessed separately in contract and operations. Buyers should test master data, integrations, migration, upgradeability and responsibility for customisations. A sector reference cannot prove identical process fit in their own ERP system.", "SAP;ERP-Integration;Handel;Prozessberatung;Stammdaten;Migration;Betrieb", "SAP;ERP integration;Trade;Process consulting;Master data;Migration;Operations", "ERP;CIO;Einkauf;Logistik;IT-Architektur;Finance;Betrieb", "ERP;CIO;Procurement;Logistics;IT architecture;Finance;Operations"],
  "GoTo":["https://www.goto.com/", "GoTo bietet Kommunikations- und IT-Support-Software für verteilte Teams. Meetings, Telefonie und Remote-Support sind getrennte Angebote mit verschiedenen Sicherheits- und Betriebsanforderungen. Käufer sollten Identitäten, Rufnummern, Supportrechte, Aufzeichnung, Integrationen und Kosten nach Nutzerrollen prüfen. Fernzugriff benötigt zeitlich begrenzte Berechtigungen und Nachweise, damit Hilfe nicht zu dauerhaftem Vollzugriff wird.", "GoTo provides communications and IT support software for distributed teams. Meetings, telephony and remote support are distinct offerings with different security and operating requirements. Buyers should assess identity, numbering, support permissions, recording, integrations and cost by user role. Remote access needs time-limited permissions and audit evidence so assistance does not become permanent broad access.", "Meetings;Telefonie;Remote-Support;IT-Management;Zusammenarbeit;Sicherheit;Integration", "Meetings;Telephony;Remote support;IT management;Collaboration;Security;Integration", "IT;Kommunikation;Service Desk;Datenschutz;Security;Operations;Einkauf", "IT;Communications;Service desk;Privacy;Security;Operations;Procurement"],
  "HiScout":["https://www.hiscout.com/", "HiScout bietet Software zur Steuerung von Informationssicherheit, Datenschutz und weiteren Governance-Prozessen. Organisationen können Risiken, Maßnahmen und Nachweise strukturiert pflegen, brauchen aber klare fachliche Verantwortliche. Käufer sollten Methodik, Berechtigungen, Vorlagen, Schnittstellen, Auditfähigkeit und Pflegeaufwand prüfen. Ein GRC-Werkzeug dokumentiert Entscheidungen, setzt technische Sicherheitsmaßnahmen aber nicht selbst um.", "HiScout provides software to manage information security, privacy and other governance processes. Organisations can maintain risks, controls and evidence in a structured way, but need clear business owners. Buyers should review methodology, permissions, templates, interfaces, auditability and maintenance effort. A GRC tool documents decisions but does not itself implement technical security controls.", "ISMS;Datenschutz;GRC;Risikomanagement;Nachweise;Audit;Maßnahmen", "ISMS;Privacy;GRC;Risk management;Evidence;Audit;Controls", "CISO;Datenschutz;Compliance;Revision;IT;Risk;Einkauf", "CISO;Privacy;Compliance;Internal audit;IT;Risk;Procurement"],
  "Hitachi Vantara":["https://www.hitachivantara.com/", "Hitachi Vantara bietet Dateninfrastruktur und Services für Unternehmensanwendungen. Speicher, Datendienste und Integrationsleistungen können unterschiedliche Betriebsmodelle und Partner umfassen. Käufer sollten Kapazität, Latenz, Ausfallsicherheit, Migration, Support und Gesamtbetriebskosten an eigenen Workloads prüfen. Ein Unternehmensbericht über Umsatz oder Strategie ist kein Nachweis für die technische Leistung einer spezifischen Konfiguration.", "Hitachi Vantara provides data infrastructure and services for enterprise applications. Storage, data services and integration work may involve different operating models and partners. Buyers should test capacity, latency, resilience, migration, support and total operating cost against their workloads. A corporate report on revenue or strategy cannot establish performance of a specific configuration.", "Enterprise Storage;Datenmanagement;Hybrid Cloud;Resilienz;Migration;Services;Integration", "Enterprise storage;Data management;Hybrid cloud;Resilience;Migration;Services;Integration", "CIO;Storage;Rechenzentrum;Cloud;IT-Betrieb;FinOps;Einkauf", "CIO;Storage;Data centres;Cloud;IT operations;FinOps;Procurement"],
  "NavVis":["https://www.navvis.com/", "NavVis entwickelt Technologie zur digitalen Erfassung und Nutzung physischer Innenräume. Laserscans und räumliche Daten können Planungs-, Betriebs- und Produktionsprozesse unterstützen. Käufer sollten Aufnahmegenauigkeit, Aktualisierung, Datenschutz, Datenformate und Integration in CAD oder Facility-Systeme prüfen. Ein digitaler Zwilling bleibt nur mit nachvollziehbaren Änderungen des realen Standorts nützlich.", "NavVis develops technology to digitally capture and use physical indoor environments. Scans and spatial data can support planning, operations and manufacturing. Buyers should assess capture accuracy, refresh processes, privacy, data formats and CAD or facilities integration. A digital twin remains useful only when changes to the physical site are reflected and traceable.", "Indoor Mapping;Laserscanning;Digitale Zwillinge;Räumliche Daten;CAD;Standortbetrieb;Integration", "Indoor mapping;Laser scanning;Digital twins;Spatial data;CAD;Site operations;Integration", "Facility;Werksplanung;Engineering;IT;Datenschutz;Produktion;Einkauf", "Facilities;Plant planning;Engineering;IT;Privacy;Production;Procurement"],
  "Net at Work GmbH – NoSpamProxy":["https://www.nospamproxy.de/", "Net at Work entwickelt mit NoSpamProxy Software für E-Mail-Sicherheit und sichere Kommunikation. Schutz vor schädlichen Nachrichten, Verschlüsselung und weitere Module erfordern passende Regeln und Mail-Integration. Käufer sollten Zustellbarkeit, Falschalarme, Schlüsselverwaltung, Datenschutz, Administration und Eskalation im produktiven Mailfluss testen. Auch gefilterte Postfächer benötigen Schulung und wirksame Identitätskontrollen.", "Net at Work develops NoSpamProxy software for email security and secure communications. Protection against malicious mail, encryption and other modules need suitable policies and mail integration. Buyers should test deliverability, false positives, key management, privacy, administration and escalation in live mail flow. Filtered mailboxes still require user training and effective identity controls.", "E-Mail-Sicherheit;NoSpamProxy;Verschlüsselung;Spamfilter;Gateway;Mail-Integration;Administration", "Email security;NoSpamProxy;Encryption;Spam filtering;Gateway;Mail integration;Administration", "CISO;Mail-Administration;IT-Betrieb;Compliance;Datenschutz;Service Desk;Einkauf", "CISO;Mail administration;IT operations;Compliance;Privacy;Service desk;Procurement"],
  "Palo Alto Networks":["https://www.paloaltonetworks.com/", "Palo Alto Networks bietet Sicherheitsplattformen für Netzwerke, Cloud und Security Operations. Firewalls, Prisma- und Cortex-Angebote erfüllen verschiedene Aufgaben und benötigen abgestimmte Richtlinien. Käufer sollten Traffic-Pfade, Identitäten, Logs, Integrationen, Lizenzen und Reaktion bei Ausfällen prüfen. Ein zentrales Dashboard verhindert keine Sicherheitslücke, wenn Zuständigkeiten und Konfigurationen über Teams hinweg ungeklärt bleiben.", "Palo Alto Networks provides security platforms for networks, cloud and security operations. Firewalls, Prisma and Cortex offerings address different needs and require coordinated policies. Buyers should assess traffic paths, identity, logs, integration, licences and outage response. A central dashboard cannot prevent a security gap when responsibility and configuration are unclear across teams.", "Firewalls;SASE;Cloud Security;Cortex;SOC;Zero Trust;Incident Response", "Firewalls;SASE;Cloud security;Cortex;SOC;Zero Trust;Incident response", "CISO;SOC;Netzwerk;Cloud;IT-Betrieb;Architektur;Einkauf", "CISO;SOC;Networking;Cloud;IT operations;Architecture;Procurement"],
  "Schneider Digital":["https://www.schneider-digital.com/", "Schneider Digital bietet professionelle Visualisierungs- und Workstation-Lösungen für anspruchsvolle 3D-Anwendungen. Displays und Komponenten müssen zu Grafiksoftware, Treibern und ergonomischen Anforderungen passen. Käufer sollten Stereoskopie, Bildqualität, Systemleistung, Kalibrierung und Support mit eigenen Datensätzen testen. Eine eindrucksvolle Demonstration bestätigt nicht automatisch die Eignung für jeden sicherheitskritischen oder medizinischen Einsatz.", "Schneider Digital offers professional visualisation and workstation solutions for demanding 3D applications. Displays and components need to match graphics software, drivers and ergonomic needs. Buyers should test stereoscopy, image quality, system performance, calibration and support using their own data. An impressive demonstration does not establish suitability for every safety-critical or medical application.", "3D-Visualisierung;Monitore;Workstations;Stereoskopie;Grafik;Kalibrierung;Support", "3D visualisation;Displays;Workstations;Stereoscopy;Graphics;Calibration;Support", "Engineering;Design;IT;Forschung;Medizinbildgebung;Technischer Einkauf;Support", "Engineering;Design;IT;Research;Medical imaging;Technical procurement;Support"],
  "Skillsoft":["https://www.skillsoft.com/", "Skillsoft bietet digitale Lerninhalte und Plattformfunktionen für berufliche Weiterbildung. Organisationen können Kurse und Lernpfade für Technologie, Führung und Compliance einsetzen; Inhalte und Sprachen variieren. Käufer sollten Lizenzmodell, Qualität, Barrierefreiheit, HR-Integration und Lernerfolg für ihre Zielgruppen prüfen. Ein KI-Coach kann Lernen begleiten, ersetzt aber weder fachliche Prüfung noch praktische Anwendung im Beruf.", "Skillsoft provides digital learning content and platform capabilities for professional development. Organisations can use courses and learning paths for technology, leadership and compliance; content and languages vary. Buyers should assess licensing, quality, accessibility, HR integration and learning outcomes for their audiences. An AI coach can support learning but not replace subject-matter validation or practical application at work.", "E-Learning;Kursbibliothek;Skills;Leadership;Compliance;KI-Coach;Lernanalyse", "E-learning;Course library;Skills;Leadership;Compliance;AI coach;Learning analytics", "HR;Learning & Development;IT;Compliance;Führung;Betriebsrat;Einkauf", "HR;Learning and development;IT;Compliance;Leadership;Works council;Procurement"],
  "Teknos Group Oy":["https://www.teknos.com/", "Teknos entwickelt Beschichtungslösungen für industrielle und bauliche Anwendungen. Beschichtungssysteme müssen zu Untergrund, Vorbehandlung, Umwelteinflüssen und Verarbeitungsprozess passen. Käufer sollten Datenblätter, Haltbarkeit, Zulassungen, Emissionen und Lieferfähigkeit für ihre Spezifikation prüfen. Ein Laborergebnis oder allgemeiner Leitfaden ersetzt keine Prüfung im konkreten Fertigungs- und Einsatzumfeld.", "Teknos develops coating solutions for industrial and building applications. Coating systems must fit substrates, pretreatment, environmental exposure and application processes. Buyers should review data sheets, durability, approvals, emissions and supply for their specification. A laboratory result or general guide cannot replace testing under the actual manufacturing and use conditions.", "Industrielacke;Beschichtungen;Holzschutz;Korrosionsschutz;Oberflächen;Anwendung;Qualität", "Industrial coatings;Coatings;Wood protection;Corrosion protection;Surfaces;Application;Quality", "Produktion;Oberflächentechnik;Qualität;Engineering;EHS;Lieferkette;Einkauf", "Manufacturing;Surface engineering;Quality;Engineering;EHS;Supply chain;Procurement"],
  "Vertex":["https://www.vertexinc.com/", "Vertex bietet Software zur Berechnung und Verwaltung indirekter Steuern in Unternehmensprozessen. Steuerlogik muss mit ERP, Ländern, Transaktionen und aktuellen Regeln zusammenpassen. Käufer sollten Integrationen, Datenqualität, Aktualisierungen, Nachweise und Ausnahmefälle mit realen Belegen prüfen. Automatisierung unterstützt die Umsetzung, ersetzt jedoch keine steuerrechtliche Bewertung ungewöhnlicher Geschäftsvorfälle.", "Vertex provides software to calculate and manage indirect tax within enterprise processes. Tax logic must fit ERP, jurisdictions, transactions and current rules. Buyers should test integrations, data quality, updates, evidence and exceptions using real documents. Automation supports execution but cannot replace tax analysis of unusual business transactions.", "Indirekte Steuern;Umsatzsteuer;Steuerautomatisierung;ERP;Compliance;Regelpflege;Audit", "Indirect tax;VAT;Tax automation;ERP;Compliance;Rule maintenance;Audit", "Steuern;CFO;ERP;Finanzen;Compliance;IT;Einkauf", "Tax;CFO;ERP;Finance;Compliance;IT;Procurement"],
  "cit":["https://www.cit.de/", "cit entwickelt Software für digitale Antrags- und Verwaltungsverfahren. Intelligente Formulare und Fallprozesse sollen Bürger, Unternehmen und Fachstellen verbinden, brauchen aber verlässliche Zuständigkeiten. Käufer sollten Barrierefreiheit, Fachverfahren, Identität, Datensicherheit und Wartbarkeit realer Anträge prüfen. KI-Unterstützung in der Verwaltung verlangt nachvollziehbare Entscheidungen und eine klare menschliche Verantwortung.", "cit develops software for digital applications and administrative procedures. Forms and case workflows connect residents, businesses and specialist offices, but need reliable responsibilities. Buyers should test accessibility, back-office systems, identity, data security and maintainability with real applications. AI support in public administration requires traceable decisions and clear human accountability.", "Digitale Verwaltung;Anträge;Formulare;Workflows;Fachverfahren;Barrierefreiheit;Integration", "Digital administration;Applications;Forms;Workflows;Specialist systems;Accessibility;Integration", "Verwaltung;Digitalisierung;IT;Datenschutz;Fachämter;Recht;Einkauf", "Public administration;Digital transformation;IT;Privacy;Departments;Legal;Procurement"],
  "GERSTEL":["https://www.gerstel.com/", "GERSTEL entwickelt Analysentechnik und Automatisierung für Labore. Probenvorbereitung und chromatografische Verfahren müssen zu Matrix, Nachweisgrenzen und Laborsoftware passen. Käufer sollten Reproduzierbarkeit, Durchsatz, Wartung, Methodenvalidierung und Schulung mit eigenen Proben testen. Eine erfolgreiche Demonstration zu einem Stoffgemisch ist kein Nachweis für andere Probenarten oder regulatorische Methoden.", "GERSTEL develops analytical instruments and automation for laboratories. Sample preparation and chromatography workflows must match sample matrices, detection limits and laboratory software. Buyers should test repeatability, throughput, maintenance, method validation and training using their own samples. A successful demonstration on one mixture does not establish performance for other samples or regulated methods.", "Laborautomation;Probenvorbereitung;Chromatografie;Analytik;Methoden;Instrumente;Service", "Laboratory automation;Sample preparation;Chromatography;Analytics;Methods;Instruments;Service", "Laborleitung;Analytik;Qualität;Forschung;Regulatory;Technik;Einkauf", "Laboratory leadership;Analytics;Quality;Research;Regulatory;Engineering;Procurement"],
  "Onapsis":["https://onapsis.com/", "Onapsis entwickelt Sicherheitslösungen für geschäftskritische Anwendungen, insbesondere SAP-Umgebungen. Schwachstellenanalyse und Überwachung müssen zu vorhandenen SAP-Landschaften, Berechtigungen und Wartungsfenstern passen. Käufer sollten Versionsabdeckung, Erkennungsqualität, Alarmwege und sichere Umsetzung von Updates prüfen. Ein Befund im ERP benötigt gemeinsame Priorisierung von Sicherheit, Basisbetrieb und Fachbereich, bevor Änderungen eingespielt werden.", "Onapsis develops security tools for business-critical applications, particularly SAP estates. Vulnerability assessment and monitoring need to fit SAP landscapes, permissions and maintenance windows. Buyers should test version coverage, detection quality, alert routes and safe implementation of updates. An ERP finding needs joint prioritisation by security, platform operations and business owners before changes are deployed.", "SAP-Sicherheit;ERP;Schwachstellen;Monitoring;Patches;Compliance;Incident Response", "SAP security;ERP;Vulnerabilities;Monitoring;Patching;Compliance;Incident response", "SAP Basis;CISO;ERP;IT-Betrieb;Compliance;Fachbereiche;Einkauf", "SAP Basis;CISO;ERP;IT operations;Compliance;Business units;Procurement"],
  "Pointsharp":["https://www.pointsharp.com/", "Pointsharp bietet Lösungen für Identitätsmanagement, sicheren Zugang und digitale Kommunikation. Produkte müssen an Verzeichnisdienste, Anwendungen und vorhandene Freigaben angebunden werden. Käufer sollten Authentisierung, Zertifikate, Benutzerlebenszyklus, Protokollierung und Notfallzugriff anhand ihrer Umgebung testen. Sichere Anmeldung allein verhindert keine übermäßigen Rechte; regelmäßige Rezertifizierung und verantwortliche Prozessinhaber bleiben erforderlich.", "Pointsharp provides identity management, secure access and digital communication solutions. Products need integrating with directories, applications and existing approvals. Buyers should test authentication, certificates, user lifecycle, logging and emergency access in their environment. Secure sign-in alone cannot prevent excessive permissions; regular recertification and accountable process owners remain necessary.", "IAM;MFA;Zertifikate;Sicherer Zugang;Identity Lifecycle;E-Mail-Sicherheit;Integration", "IAM;MFA;Certificates;Secure access;Identity lifecycle;Email security;Integration", "CISO;IAM;IT-Betrieb;Compliance;HR;Architektur;Einkauf", "CISO;IAM;IT operations;Compliance;HR;Architecture;Procurement"],
  "Real-Time Innovations, Inc. (RTI)":["https://www.rti.com/", "Real-Time Innovations entwickelt Dateninfrastruktur für verteilte, zeitkritische Systeme. Connext auf Basis von DDS verbindet Anwendungen und Geräte, deren Latenz- und Verfügbarkeitsanforderungen stark variieren. Käufer sollten Interoperabilität, Datenmodelle, deterministisches Verhalten und Sicherheitsfunktionen mit eigener Hardware testen. Eine Referenz aus autonomen Systemen ersetzt keine Validierung der konkreten sicherheitskritischen Architektur.", "Real-Time Innovations develops data infrastructure for distributed, time-sensitive systems. Connext based on DDS connects applications and devices whose latency and availability requirements vary widely. Buyers should test interoperability, data models, deterministic behaviour and security functions on their own hardware. An autonomous-systems reference cannot replace validation of a particular safety-critical architecture.", "DDS;Connext;Echtzeitdaten;Industrial IoT;Autonome Systeme;Interoperabilität;Sicherheit", "DDS;Connext;Real-time data;Industrial IoT;Autonomous systems;Interoperability;Security", "Embedded Engineering;OT;Architektur;Safety;Forschung;IT;Einkauf", "Embedded engineering;OT;Architecture;Safety;Research;IT;Procurement"],
  "Spreadly":["https://spreadly.app/", "Spreadly bietet digitale Visitenkarten und Werkzeuge für die Verwaltung beruflicher Kontaktdaten. Teams können Markenauftritt und Verteilung zentral steuern; Integration und Datenpflege hängen vom eigenen CRM und Nutzerverhalten ab. Käufer sollten SSO, Rechte, Export, Datenschutz und Übergabe bei Personalwechsel prüfen. Eine digitale Kontaktkarte ist keine Einwilligung zur Werbeansprache oder automatische Bestätigung aktueller CRM-Daten.", "Spreadly provides digital business cards and tools to manage professional contact information. Teams can control branding and distribution centrally; integration and data quality depend on their CRM and user behaviour. Buyers should test SSO, permissions, export, privacy and handover when staff leave. A digital contact card does not constitute consent to marketing or confirm that CRM records are current.", "Digitale Visitenkarten;Kontaktdaten;CRM-Integration;Branding;SSO;Sharing;Datenschutz", "Digital business cards;Contact data;CRM integration;Branding;SSO;Sharing;Privacy", "Vertrieb;Marketing;HR;IT;Datenschutz;CRM;Einkauf", "Sales;Marketing;HR;IT;Privacy;CRM;Procurement"],
  "Sycor":["https://sycor-group.com/", "Sycor berät und implementiert Unternehmenssoftware für Branchenprozesse und digitale Transformation. Cloud- und ERP-Projekte können verschiedene Plattformen und Implementierungspartner umfassen. Auftraggeber sollten Branchenfunktionen, Datenmigration, Integrationen, laufenden Support und Lizenzverantwortung konkret vereinbaren. Eine digitale Roadmap hilft nur, wenn Prozessinhaber und messbare Übergänge in den Betrieb feststehen.", "Sycor advises on and implements enterprise software for industry processes and digital transformation. Cloud and ERP projects can involve different platforms and implementation partners. Clients should agree industry functions, data migration, integration, continued support and licence responsibility. A digital roadmap only helps when process owners and measurable transitions to operations are defined.", "ERP;Cloud;Branchenlösungen;Systemintegration;Migration;Beratung;Managed Services", "ERP;Cloud;Industry solutions;Systems integration;Migration;Consulting;Managed services", "CIO;ERP;Fachbereiche;Produktion;IT-Betrieb;Finanzen;Einkauf", "CIO;ERP;Business units;Manufacturing;IT operations;Finance;Procurement"],
  "TQ-Group":["https://www.tq-group.com/", "TQ-Group entwickelt und fertigt Elektronik und mechatronische Systeme für unterschiedliche Industrien. Module, Embedded-Computing und Produktionsleistungen haben jeweils andere Zertifizierungs- und Lieferanforderungen. Käufer sollten Entwicklungsverantwortung, Stückzahlen, Komponentenverfügbarkeit, Tests und Änderungsmanagement vor Serienstart klären. Ein Prototyp beweist noch keine stabile Versorgung oder reproduzierbare Qualität der Serie.", "TQ-Group develops and manufactures electronics and mechatronic systems for varied industries. Modules, embedded computing and manufacturing services have different certification and supply requirements. Buyers should clarify development responsibility, volumes, component availability, tests and change control before series production. A prototype cannot prove stable supply or repeatable quality at scale.", "Elektronikentwicklung;Embedded Computing;Fertigung;Mechatronik;Module;Tests;Lieferkette", "Electronics development;Embedded computing;Manufacturing;Mechatronics;Modules;Testing;Supply chain", "Entwicklung;Produktion;Qualität;Supply Chain;Produktmanagement;Technik;Einkauf", "Development;Manufacturing;Quality;Supply chain;Product management;Engineering;Procurement"],
  "Xeneta":["https://www.xeneta.com/", "Xeneta bietet Daten und Analysen für Frachtraten und Transportmärkte. Einkauf und Logistik können Preisentwicklungen vergleichen, müssen dabei Route, Zeitraum und Vertragsbedingungen berücksichtigen. Käufer sollten Datenabdeckung, Aktualität, Vergleichbarkeit, API-Zugriff und Vertraulichkeit eigener Konditionen prüfen. Ein Benchmark ist ein Verhandlungssignal, kein garantierter Marktpreis für das eigene Sendungsprofil.", "Xeneta provides data and analytics for freight rates and transport markets. Procurement and logistics teams can compare pricing trends while accounting for lane, period and contract terms. Buyers should assess data coverage, freshness, comparability, API access and confidentiality of their own rates. A benchmark is a negotiation signal, not a guaranteed market price for their shipment profile.", "Frachtraten;Benchmarking;Transportdaten;Logistik;Beschaffung;Marktanalyse;API", "Freight rates;Benchmarking;Transport data;Logistics;Procurement;Market analysis;API", "Transportleitung;Logistik;Einkauf;Supply Chain;Finanzen;Analytics;IT", "Transport leadership;Logistics;Procurement;Supply chain;Finance;Analytics;IT"],
  "Zimperium":["https://www.zimperium.com/", "Zimperium bietet Sicherheitslösungen für mobile Endgeräte und Anwendungen. Mobile Threat Defense und App-Schutz adressieren verschiedene Risiken; Einbindung in UEM und Incident-Prozesse ist entscheidend. Käufer sollten Geräteabdeckung, Signale, Falschalarme, App-Tests und Datenschutz prüfen. Ein geschütztes Telefon ersetzt keine Kontrolle der Berechtigungen, sicheren Entwicklung oder Sensibilisierung gegen mobile Phishing-Angriffe.", "Zimperium offers security solutions for mobile devices and applications. Mobile threat defence and app protection address different risks; integration with UEM and incident processes matters. Buyers should test device coverage, signals, false positives, app testing and privacy. A protected phone cannot replace permission control, secure development or awareness of mobile phishing.", "Mobile Threat Defense;App-Sicherheit;UEM-Integration;Phishing;Endpunkte;Monitoring;Incident Response", "Mobile threat defence;App security;UEM integration;Phishing;Endpoints;Monitoring;Incident response", "CISO;Mobile IT;App-Entwicklung;SOC;Datenschutz;UEM;Einkauf", "CISO;Mobile IT;App development;SOC;Privacy;UEM;Procurement"],
  "IONOS":["https://www.ionos.de/", "IONOS bietet Hosting, Domains, Cloud-Infrastruktur und Online-Dienste für Unternehmen. Ein Webhosting-Paket, dedizierte Cloud-Ressourcen und verwaltete Angebote haben unterschiedliche Leistungs- und Verantwortungsgrenzen. Käufer sollten Standort, Verfügbarkeit, Backups, Sicherheitsfunktionen, Support und Datenexport je Produkt prüfen. Eine regionale Serverangabe allein klärt weder alle Unterauftragsverarbeiter noch die Sicherung der eigenen Anwendungen.", "IONOS provides hosting, domains, cloud infrastructure and online services for businesses. Shared hosting, dedicated cloud resources and managed offerings differ in service and responsibility boundaries. Buyers should assess location, availability, backup, security, support and data export by product. A regional server claim alone cannot clarify every subprocessor or protection of customer applications.", "Webhosting;Domains;Cloud-Server;Storage;Managed Services;Backup;E-Commerce", "Web hosting;Domains;Cloud servers;Storage;Managed services;Backup;E-commerce", "IT;Webbetrieb;Cloud;Datenschutz;Sicherheit;KMU-Leitung;Einkauf", "IT;Web operations;Cloud;Privacy;Security;SME management;Procurement"],
  "NewTec":["https://www.newtec.de/", "NewTec entwickelt Embedded-Software und Systeme für industrielle und sicherheitsrelevante Anwendungen. Entwicklungsleistungen, Sicherheitsnachweise und Serienintegration hängen von Produkt und Normenumfeld ab. Käufer sollten Architektur, Testabdeckung, Dokumentation, Änderungsprozess und Zuständigkeit für Zertifizierung vereinbaren. Ein Konzept für funktionale Sicherheit braucht Nachweise in der konkreten Geräte- und Systemkonfiguration.", "NewTec develops embedded software and systems for industrial and safety-related applications. Development services, safety evidence and series integration depend on the product and standards environment. Buyers should specify architecture, test coverage, documentation, change process and certification responsibility. A functional-safety concept needs evidence for the specific device and system configuration.", "Embedded Software;Functional Safety;Elektronik;Systementwicklung;Tests;Zertifizierung;Industrie", "Embedded software;Functional safety;Electronics;Systems engineering;Testing;Certification;Industry", "Entwicklung;Safety;Qualität;Produktmanagement;Fertigung;Technischer Einkauf;Regulatory", "Development;Safety;Quality;Product management;Manufacturing;Technical procurement;Regulatory"],
  "OEDIV Oetker Daten- und Informationsverarbeitung KG":["https://www.oediv.de/", "OEDIV stellt IT-Dienstleistungen für Unternehmen bereit, darunter Infrastruktur, Cloud- und SAP-nahe Betriebsleistungen. Leistungsumfang und Verantwortung variieren nach Managed-Service-Vertrag und Partnertechnologie. Käufer sollten Rechenzentrumsstandorte, Verfügbarkeit, Recovery, Zugriffsrechte und Eskalation anhand eigener Anwendungen prüfen. Ein Outsourcing-Vertrag erfordert klare Grenzen zwischen Kundenanwendung, Plattformbetrieb und Sicherheitsaufgaben.", "OEDIV provides enterprise IT services including infrastructure, cloud and SAP-related operations. Service scope and responsibility vary by managed-service contract and partner technology. Buyers should assess data-centre locations, availability, recovery, access rights and escalation using their applications. An outsourcing agreement needs clear boundaries between customer applications, platform operations and security tasks.", "Managed IT;Rechenzentrum;SAP-Betrieb;Cloud;Backup;Security;Service Management", "Managed IT;Data centres;SAP operations;Cloud;Backup;Security;Service management", "CIO;SAP;IT-Betrieb;Cloud;CISO;Business Continuity;Einkauf", "CIO;SAP;IT operations;Cloud;CISO;Business continuity;Procurement"],
  "nLighten":["https://www.nlighten.com/en/", "nLighten betreibt regionale Rechenzentrumsstandorte für Colocation und Konnektivität. Standortnähe kann für Latenz und lokale Betriebsprozesse relevant sein, während Ausstattung und Dienste je Gebäude variieren. Käufer sollten Strom, Kühlung, Netzpartner, Zugang, Nachhaltigkeitsdaten und Service Level je Standort prüfen. Eine Gruppenbeschreibung ersetzt keine technische Besichtigung oder belastbare Kapazitätszusage am konkreten Standort.", "nLighten operates regional data-centre sites for colocation and connectivity. Local proximity can matter for latency and operations, while facilities and services differ by building. Buyers should assess power, cooling, network partners, access, sustainability data and service levels by site. A group description cannot replace a technical visit or firm capacity commitment for a specific location.", "Colocation;Edge-Rechenzentren;Konnektivität;Strom;Kühlung;Standorte;Nachhaltigkeit", "Colocation;Edge data centres;Connectivity;Power;Cooling;Sites;Sustainability", "CIO;Rechenzentrum;Netzwerk;Facility;Finanzen;Nachhaltigkeit;Einkauf", "CIO;Data centres;Networking;Facilities;Finance;Sustainability;Procurement"],
  "Minol-ZENNER-Gruppe":["https://www.minol.de/", "Die Minol-ZENNER-Gruppe bietet Mess-, Abrechnungs- und digitale Dienstleistungen für Gebäude und Versorgungsinfrastruktur. Geräte, Funknetze und Abrechnungsservice haben unterschiedliche Verantwortlichkeiten. Käufer sollten Messgenauigkeit, Ablesung, Datenzugriff, Mieterkommunikation und gesetzliche Fristen je Angebot prüfen. Ein IoT-Netz ist noch keine vollständige Abrechnungslösung; Schnittstellen und Datenqualität müssen stimmen.", "The Minol-ZENNER group provides metering, billing and digital services for buildings and utility infrastructure. Devices, radio networks and billing services carry different responsibilities. Buyers should assess measurement accuracy, reading, data access, tenant communication and statutory deadlines by offer. An IoT network is not a complete billing solution; interfaces and data quality matter.", "Messdienst;Verbrauchsdaten;Abrechnung;IoT;Funk;Gebäude;Energie", "Metering;Consumption data;Billing;IoT;Wireless;Buildings;Energy", "Immobilienverwaltung;Facility;Energie;Datenschutz;IT;Finanzen;Einkauf", "Property management;Facilities;Energy;Privacy;IT;Finance;Procurement"],
  "S-Public Services":["https://www.s-publicservices.de/", "S-Public Services unterstützt digitale Zahlungsprozesse für öffentliche Stellen und angrenzende Organisationen. Verfahren müssen zu Fachanwendungen, Zahlarten und kommunalen Kassenprozessen passen. Käufer sollten Integration, Abgleich, Gebühren, Barrierefreiheit, Datenschutz und Verantwortlichkeiten bei Zahlungsstörungen prüfen. Eine verfügbare Zahlart allein bestätigt keinen vollständig medienbruchfreien Verwaltungsprozess.", "S-Public Services supports digital payment processes for public bodies and related organisations. Workflows need to fit specialist applications, payment methods and municipal treasury processes. Buyers should test integration, reconciliation, fees, accessibility, privacy and responsibility during payment failures. Availability of a payment method alone does not establish a fully digital administrative process.", "E-Payment;Kommunen;Zahlarten;Kassenintegration;Abgleich;Verwaltung;Schnittstellen", "E-payment;Municipalities;Payment methods;Treasury integration;Reconciliation;Public administration;Interfaces", "Kämmerei;Verwaltung;IT;Bürgerdienste;Datenschutz;Finanzen;Einkauf", "Treasury;Administration;IT;Citizen services;Privacy;Finance;Procurement"],
  "cashwerk":["https://cashwerk.io/", "cashwerk verbindet CRM, Projekte, Zeiterfassung und Rechnungen in einer Plattform für kleinere Unternehmen. Der E-Form Builder soll Formulare und ihre Anbindung an interne Abläufe erleichtern. Käufer sollten Feldlogik, Datenrechte, Integrationen, Freigaben und die Überprüfung KI-generierter Formulare testen. Eine schnell erstellte Eingabemaske garantiert noch keine korrekte Verarbeitung oder den rechtmäßigen Umgang mit Kundendaten.", "cashwerk combines CRM, projects, time tracking and invoicing in a platform for smaller organisations. Its E-Form Builder aims to simplify form creation and integration with internal workflows. Buyers should test field logic, data rights, integration, approvals and review of AI-generated forms. A quickly created input screen does not guarantee correct processing or lawful handling of customer data.", "CRM;Digitale Formulare;E-Form Builder;Projekte;KI-Assistent;Zeiterfassung;Rechnungen", "CRM;Digital forms;E-Form Builder;Projects;AI assistant;Time tracking;Invoicing", "Geschäftsführung;Operations;IT;Prozessmanagement;Vertrieb;Datenschutz;Einkauf", "Management;Operations;IT;Process management;Sales;Privacy;Procurement"],
  "Alpein Software Swiss":["https://www.alpeinsoft.ch/", "Alpein Software Swiss entwickelt Lösungen für sicheren Datenaustausch und digitale Zusammenarbeit. Konkrete Funktionen und Hosting hängen von Produkt und Vertrag ab. Käufer sollten Identitäten, Verschlüsselung, Berechtigungen, Datenstandort, Audit und Integration in vorhandene Systeme prüfen. Der Standort eines Softwareanbieters allein beantwortet nicht, wo alle Daten verarbeitet werden oder welche Unterauftragnehmer beteiligt sind.", "Alpein Software Swiss develops solutions for secure data exchange and digital collaboration. Specific features and hosting depend on product and contract. Buyers should examine identities, encryption, permissions, data location, audit and integration with existing systems. A software vendor's home country alone cannot establish where all data is processed or which subcontractors participate.", "Sichere Zusammenarbeit;Datenaustausch;Verschlüsselung;Identitäten;Cloud;Berechtigungen;Audit", "Secure collaboration;Data exchange;Encryption;Identity;Cloud;Permissions;Audit", "CISO;IT;Datenschutz;Compliance;Fachbereiche;Architektur;Einkauf", "CISO;IT;Privacy;Compliance;Business units;Architecture;Procurement"],
  "AOC International (Europe)":["https://aoc.com/", "AOC bietet Monitore für Arbeitsplätze und weitere Nutzungsszenarien. Für Unternehmen zählen Auflösung, Anschlüsse, Ergonomie, Energieverbrauch und Garantie; Gaming-Geräte haben andere Prioritäten als Büroausstattung. Käufer sollten Geräte mit vorhandenen Dockingstationen, Arbeitsplätzen und Barrierefreiheitsanforderungen testen. Eine hohe Bildwiederholrate allein verbessert keine Arbeitsplatzergonomie.", "AOC supplies monitors for workplaces and other use cases. Business selection involves resolution, connectivity, ergonomics, energy use and warranty; gaming displays prioritise different features from office equipment. Buyers should test devices with existing docks, desks and accessibility requirements. A high refresh rate alone cannot improve workplace ergonomics.", "Monitore;Displays;Ergonomie;Anschlüsse;Bildqualität;Energie;Garantie", "Monitors;Displays;Ergonomics;Connectivity;Image quality;Energy;Warranty", "IT-Einkauf;Workplace;Facility;HR;Design;Service Desk;Nachhaltigkeit", "IT procurement;Workplace;Facilities;HR;Design;Service desk;Sustainability"],
  "Nexia":["https://nexia.com/", "Nexia ist ein internationales Netzwerk selbstständiger Beratungs- und Prüfungsgesellschaften. Die Leistung entsteht durch die jeweilige Mitgliedsfirma; Angebote und Zulassungen sind lokal zu prüfen. Mandanten sollten Mandatspartei, Fachkompetenz, Unabhängigkeit, Länderkoordination und Datenschutz klären. Ein globales Netzwerk garantiert keine einheitliche Qualität oder automatische gegenseitige Haftung aller Mitglieder.", "Nexia is an international network of independent advisory and accountancy firms. Services are delivered by individual members; offerings and professional authorisations need checking locally. Clients should clarify the contracting firm, expertise, independence, cross-border coordination and privacy. A global network does not guarantee identical quality or shared liability among all members.", "Wirtschaftsprüfung;Steuern;Beratung;Internationale Koordination;Compliance;Transaktionen;Netzwerk", "Audit;Tax;Advisory;International coordination;Compliance;Transactions;Network", "CFO;Steuern;Revision;Recht;Geschäftsführung;Compliance;Einkauf", "CFO;Tax;Audit;Legal;Management;Compliance;Procurement"],
  "ACP IT Solutions":["https://www.acp-gruppe.com/", "ACP IT Solutions unterstützt Unternehmen mit IT-Infrastruktur, Modernisierung und Serviceleistungen. Projekte können Hardware, Cloud-Plattformen und Partnerprodukte verbinden, deren Garantie- und Betriebspflichten getrennt zu regeln sind. Käufer sollten Standortbetreuung, Servicezeiten, Migration, Sicherheit und Übergabe an eigene Teams vereinbaren. Eine breite Herstellerpartnerschaft beweist keine konkrete Lieferfähigkeit oder Erfahrung mit jeder Produktkonfiguration.", "ACP IT Solutions supports organisations with IT infrastructure, modernisation and services. Projects may combine hardware, cloud platforms and partner products, whose warranties and operational duties require separate agreement. Buyers should define local support, service hours, migration, security and handover to internal teams. A broad vendor partnership does not demonstrate availability or experience with every product configuration.", "IT-Infrastruktur;Cloud;Workplace;Systemintegration;Managed Services;Sicherheit;Support", "IT infrastructure;Cloud;Workplace;Systems integration;Managed services;Security;Support", "CIO;IT-Betrieb;Cloud;Workplace;Sicherheit;Service Management;Einkauf", "CIO;IT operations;Cloud;Workplace;Security;Service management;Procurement"],
};

const fields=(value:string)=>value.split(";");
export const providerProfilesThird:Record<string,ProviderProfile>=Object.fromEntries(Object.entries(rows).map(([name,[officialUrl,de,en,fd,fe,rd,re]])=>[name,{
  officialUrl,officialLabel:{de:`Offizielle Anbieterquelle: ${name}`,en:`Official provider source: ${name}`},
  metaDescription:{de:de.split(". ")[0]+".",en:en.split(". ")[0]+"."},
  summary:{de,en},focus:{de:fields(fd),en:fields(fe)},buyerGroups:{de:fields(rd),en:fields(re)}
}]));
